const logo = `${import.meta.env.BASE_URL}alasas-logo.jpg`
const floralFallback = `${import.meta.env.BASE_URL}uploads/floor-232bc/category/demoGraduation/1792011071663-d76e1185fe0247808785b2bd192b417f.jpg`
// Images are either managed store URLs or checked-in local assets. Never turn an
// opaque database value into a third-party stock-image URL.
const image = (..._ignored: unknown[]) => logo
const configuredImage = (value: unknown, fallback: string) => typeof value === 'string' && /^(https?:\/\/|\/)/i.test(value.trim()) ? value.trim() : fallback

type Product = { id: string; name: string; en: string; price: number; compareAtPrice?: number; discountPercent?: number; category: string; image: string; imageUrls?: string[]; badge?: string; packaging?: string; colors?: string[]; addOns?: string[]; flowerType?: string; occasions?: string[]; featured?: boolean; bestseller?: boolean; isNew?: boolean; stock?: number; tone: string; description: string; demo?: boolean; orderable?: boolean }
const money = (n: number) => `${n.toLocaleString('en-US')} د.ع`
const favoriteStorageKey = 'alasas-favorites'
function favoriteKey() { return `${favoriteStorageKey}:${firebaseAuth.currentUser?.uid || 'guest'}` }
function readFavoriteIds(): string[] { try { const value = JSON.parse(localStorage.getItem(favoriteKey()) || '[]'); return Array.isArray(value) ? [...new Set(value.filter((id): id is string => typeof id === 'string' && /^[A-Za-z0-9_-]{1,120}$/.test(id)))].slice(0, 200) : [] } catch { return [] } }
async function syncFavoriteIdsToAccount(ids: string[]) { const user = firebaseAuth.currentUser; if (!user) return; await set(ref(firebaseDatabase, `users/${user.uid}/favorites`), Object.fromEntries(ids.slice(0, 200).map(id => [id, true]))) }
function toggleFavoriteId(id: string): boolean { const current = readFavoriteIds(); const next = current.includes(id) ? current.filter(item => item !== id) : [...current, id]; localStorage.setItem(favoriteKey(), JSON.stringify(next)); void syncFavoriteIdsToAccount(next).catch(() => undefined); window.dispatchEvent(new Event('alasas-favorites-changed')); return next.includes(id) }
function FavoriteAccountSync() { useEffect(() => onAuthStateChanged(firebaseAuth, user => { if (!user) return; const guestIds = (() => { try { const value = JSON.parse(localStorage.getItem(`${favoriteStorageKey}:guest`) || '[]'); return Array.isArray(value) ? value.filter((id): id is string => typeof id === 'string') : [] } catch { return [] } })(); void get(ref(firebaseDatabase, `users/${user.uid}/favorites`)).then(snapshot => { const accountIds = snapshot.exists() && snapshot.val() && typeof snapshot.val() === 'object' ? Object.entries(snapshot.val()).filter(([, value]) => value === true).map(([id]) => id) : []; const ids = [...new Set([...accountIds, ...guestIds])].slice(0, 200); localStorage.setItem(`${favoriteStorageKey}:${user.uid}`, JSON.stringify(ids)); return syncFavoriteIdsToAccount(ids) }).then(() => { localStorage.removeItem(`${favoriteStorageKey}:guest`); window.dispatchEvent(new Event('alasas-favorites-changed')) }).catch(() => undefined) }), []); return null }

type CatalogState = { products: Product[]; realProducts: Product[]; categories: [string, string, string][]; live: boolean; loading: boolean; error: string; retry: () => void; publicConfig: ShopPublicConfig; giftConfig: GiftConfig }
const CatalogContext = createContext<CatalogState | null>(null)
const fallbackProductImage = `${import.meta.env.BASE_URL}alasas-logo.jpg`
function mapCatalogProduct(record: FlowerProductRecord): Product {
  return {
    id: record.id,
    name: record.name,
    en: record.nameEn || record.name,
    price: record.price,
    ...(record.compareAtPrice ? { compareAtPrice: record.compareAtPrice } : {}),
    ...(record.discountPercent ? { discountPercent: record.discountPercent } : {}),
    ...(record.packaging ? { packaging: record.packaging } : {}),
    ...(record.colors?.length ? { colors: record.colors } : {}),
    ...(record.addOns?.length ? { addOns: record.addOns } : {}),
    ...(record.flowerType ? { flowerType: record.flowerType } : {}),
    ...(record.occasions?.length ? { occasions: record.occasions } : {}),
    ...(record.featured ? { featured: true } : {}),
    ...(record.bestseller ? { bestseller: true } : {}),
    ...(record.isNew ? { isNew: true } : {}),
    ...(typeof record.stock === 'number' ? { stock: record.stock } : {}),
    category: record.category,
    image: record.image || record.imageUrls?.[0] || fallbackProductImage,
    ...(record.imageUrls?.length ? { imageUrls: record.imageUrls } : {}),
    description: record.description || 'منتج متاح من متجر الأساس.',
    tone: '#b7ff2a',
    ...(record.demo ? { demo: true } : {}),
    orderable: record.orderable !== false && record.demo !== true,
  }
}
function CatalogProvider({ children }: { children: React.ReactNode }) {
  const [records, setRecords] = useState<FlowerProductRecord[]>([])
  const [demoRecords, setDemoRecords] = useState<FlowerProductRecord[]>([])
  const [categoryRecords, setCategoryRecords] = useState<FlowerCategoryRecord[]>([])
  const [publicConfig, setPublicConfig] = useState<ShopPublicConfig>({ paymentMethods: {}, delivery: {}, settings: {}, homepage: DEFAULT_HOMEPAGE_CONFIG, aiAssistant: DEFAULT_AI_ASSISTANT_CONFIG })
  const [giftConfig, setGiftConfig] = useState<GiftConfig>(EMPTY_GIFT_CONFIG)
  const [loading, setLoading] = useState(true)
  const [sourceErrors, setSourceErrors] = useState<Record<string, string>>({})
  const [retryToken, setRetryToken] = useState(0)
  const setSourceError = (source: string, reason?: Error) => setSourceErrors(current => {
    const next = { ...current }
    if (reason) next[source] = reason.message || 'تعذر الاتصال بـ Firebase.'
    else delete next[source]
    return next
  })
  const retry = () => setRetryToken(value => value + 1)
  useEffect(() => { setLoading(true); return subscribeToShopProducts('floor-232bc', value => { setRecords(value); setLoading(false); setSourceError('products') }, reason => { setSourceError('products', reason); setLoading(false) }) }, [retryToken])
  useEffect(() => subscribeToShopDemoProducts('floor-232bc', value => { setDemoRecords(value); setSourceError('demoProducts') }, reason => setSourceError('demoProducts', reason)), [retryToken])
  useEffect(() => subscribeToShopCategories('floor-232bc', value => { setCategoryRecords(value); setSourceError('categories') }, reason => setSourceError('categories', reason)), [retryToken])
  useEffect(() => subscribeToShopPublicConfig('floor-232bc', value => { setPublicConfig(value); setSourceError('publicConfig') }, reason => setSourceError('publicConfig', reason)), [retryToken])
  useEffect(() => subscribeToShopGiftConfig('floor-232bc', value => { setGiftConfig(value); setSourceError('gifting') }, reason => setSourceError('gifting', reason)), [retryToken])
  useEffect(() => {
    const settings = publicConfig.settings as Record<string, unknown>
    const assistant = publicConfig.aiAssistant as Record<string, unknown>
    const root = document.documentElement
    const colors: Record<string, string> = {
      '--store-primary': 'primaryColor',
      '--store-secondary': 'secondaryColor',
      '--store-button': 'buttonColor',
      '--store-text': 'textColor',
      '--store-background': 'backgroundColor',
      '--store-header': 'headerColor',
      '--store-footer': 'footerColor',
    }
    Object.entries(colors).forEach(([cssName, field]) => {
      const value = typeof settings[field] === 'string' ? settings[field] as string : ''
      if (/^#[0-9a-f]{6}$/i.test(value)) root.style.setProperty(cssName, value)
      else root.style.removeProperty(cssName)
    })
  }, [publicConfig.settings, publicConfig.aiAssistant])
  const liveProducts = records.map(mapCatalogProduct)
  const demoProducts = demoRecords.map(mapCatalogProduct)
  const liveCategories: [string, string, string][] = categoryRecords.map(record => [record.name, record.description || 'اكتشف تشكيلات المتجر', record.image || floralFallback])
  const error = Object.values(sourceErrors).find(Boolean) || ''
  return <CatalogContext.Provider value={{ products: [...liveProducts, ...demoProducts], realProducts: liveProducts, categories: liveCategories, live: liveProducts.length > 0, loading, error, retry, publicConfig, giftConfig }}>{children}</CatalogContext.Provider>
}
function useCatalog() { const value = useContext(CatalogContext); if (!value) throw new Error('useCatalog must be used inside CatalogProvider'); return value }
function CatalogConnectionNotice() {
  const { loading, error, retry } = useCatalog(); const [online, setOnline] = useState(() => navigator.onLine)
  useEffect(() => { const changed = () => setOnline(navigator.onLine); window.addEventListener('online', changed); window.addEventListener('offline', changed); return () => { window.removeEventListener('online', changed); window.removeEventListener('offline', changed) } }, [])
  if (!online) return <div className="demo-note" role="status">أنت غير متصل حالياً؛ ستتحدث البيانات تلقائياً بعد عودة الاتصال.</div>
  if (loading) return <div className="demo-note" role="status">جارٍ تحميل الكتالوج من Firebase...</div>
  if (error) return <div className="demo-note" role="alert">تعذر تحديث بيانات Firebase؛ لم نستخدم بيانات بديلة. <button type="button" onClick={retry}>إعادة المحاولة</button></div>
  return null
}

type CartCard = { id: string; text: string; image?: string; message?: string }
type CartGifting = { optionIds?: Record<string, string>; addonIds?: string[]; cardId?: string; cardMessage?: string }
type CartOptions = { packaging?: string; packagingColor?: string; giftMessage?: string; addOns?: string[]; card?: CartCard; gifting?: CartGifting }
type CartLine = { lineId: string; productId: string; quantity: number } & CartOptions
function cartLineKey(productId: string, options: CartOptions = {}) {
  return `${productId}:${JSON.stringify({ packaging: options.packaging || '', packagingColor: options.packagingColor || '', giftMessage: options.giftMessage || '', addOns: [...(options.addOns || [])].sort(), card: options.card ? { id: options.card.id, message: options.card.message || '' } : null, gifting: options.gifting ? { optionIds: options.gifting.optionIds || {}, addonIds: [...(options.gifting.addonIds || [])].sort(), cardId: options.gifting.cardId || '', cardMessage: options.gifting.cardMessage || '' } : null })}`
}
type CartState = {
  items: CartLine[]
  count: number
  add: (productId: string, quantity?: number, options?: CartOptions) => void
  setQuantity: (lineId: string, quantity: number) => void
  remove: (lineId: string) => void
  clear: () => void
}
function useCart(): CartState {
  const [items, setItems] = useState<CartLine[]>(() => {
    try {
      const stored = JSON.parse(localStorage.getItem('alasas-cart') || '[]')
      return Array.isArray(stored) ? stored.filter(item => typeof item?.productId === 'string' && Number.isInteger(item.quantity) && item.quantity > 0).map(item => {
        const rawCard = item.card && typeof item.card === 'object' && typeof item.card.id === 'string' && typeof item.card.text === 'string' ? { id: item.card.id, text: item.card.text, ...(typeof item.card.image === 'string' ? { image: item.card.image } : {}), ...(typeof item.card.message === 'string' ? { message: item.card.message.slice(0, 2000) } : {}) } : undefined
        const rawGifting = item.gifting && typeof item.gifting === 'object' ? { optionIds: item.gifting.optionIds && typeof item.gifting.optionIds === 'object' ? item.gifting.optionIds : {}, addonIds: Array.isArray(item.gifting.addonIds) ? item.gifting.addonIds.filter((value: unknown): value is string => typeof value === 'string') : [], ...(typeof item.gifting.cardId === 'string' ? { cardId: item.gifting.cardId } : {}), ...(typeof item.gifting.cardMessage === 'string' ? { cardMessage: item.gifting.cardMessage.slice(0, 2000) } : {}) } : undefined
        const options: CartOptions = { ...(typeof item.packaging === 'string' ? { packaging: item.packaging } : {}), ...(typeof item.packagingColor === 'string' ? { packagingColor: item.packagingColor } : {}), ...(typeof item.giftMessage === 'string' ? { giftMessage: item.giftMessage } : {}), ...(Array.isArray(item.addOns) ? { addOns: item.addOns.filter((value: unknown): value is string => typeof value === 'string') } : {}), ...(rawCard ? { card: rawCard } : {}), ...(rawGifting ? { gifting: rawGifting } : {}) }
        return { lineId: typeof item.lineId === 'string' ? item.lineId : cartLineKey(item.productId, options), productId: item.productId, quantity: item.quantity, ...options }
      }) : []
    } catch { return [] }
  })
  const persist = (next: CartLine[]) => { setItems(next); localStorage.setItem('alasas-cart', JSON.stringify(next)) }
  const add = (productId: string, quantity = 1, options: CartOptions = {}) => {
    const lineId = cartLineKey(productId, options)
    const current = items.find(item => item.lineId === lineId)
    const next = current ? items.map(item => item.lineId === lineId ? { ...item, quantity: item.quantity + quantity } : item) : [...items, { lineId, productId, quantity, ...options }]
    persist(next)
  }
  const setQuantity = (lineId: string, quantity: number) => persist(quantity > 0 ? items.map(item => item.lineId === lineId ? { ...item, quantity } : item) : items.filter(item => item.lineId !== lineId))
  const remove = (lineId: string) => persist(items.filter(item => item.lineId !== lineId))
  const clear = () => persist([])
  return { items, count: items.reduce((sum, item) => sum + item.quantity, 0), add, setQuantity, remove, clear }
}

function App() {
  const cart = useCart(); const location = useLocation(); const [menu, setMenu] = useState(false); const [toast, setToast] = useState('')
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2600) }
  if (location.pathname.startsWith('/admin')) return <Routes><Route path="/admin/*" element={<AdminGate><AdminApp /></AdminGate>} /></Routes>
  return <CatalogProvider><div className="app-shell">
    <FavoriteAccountSync />
    <Announcement />
    <Header menu={menu} setMenu={setMenu} cartCount={cart.count} />
    <CatalogConnectionNotice />
    <AnimatePresence>{toast && <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="toast"><Check size={16} /> {toast}</motion.div>}</AnimatePresence>
    {location.pathname === '/checkout' && <CheckoutReview cart={cart} />}
    <Routes>
      <Route path="/" element={<Home onAdd={(id) => { cart.add(id); notify('تمت إضافة الباقة إلى السلة') }} />} />
      <Route path="/shop" element={<Shop onAdd={(id) => { cart.add(id); notify('تمت إضافة المنتج إلى السلة') }} />} />
      <Route path="/product/:slug" element={<ProductPage onAdd={(id, quantity, options) => { cart.add(id, quantity, options); notify('تمت إضافة المنتج إلى السلة') }} />} />
      <Route path="/gifting" element={<Navigate to="/send-a-gift" replace />} />
      <Route path="/send-a-gift" element={<GiftPageV2 onAdd={(id, options) => { cart.add(id, 1, options); notify('تمت إضافة الهدية إلى السلة') }} />} />
      <Route path="/bouquet-builder" element={<BouquetBuilderV2 onAdd={(id, options) => { cart.add(id, 1, options); notify('تمت إضافة الباقة المخصصة إلى السلة') }} />} />
      <Route path="/design-your-bouquet" element={<BouquetBuilderV2 onAdd={(id, options) => { cart.add(id, 1, options); notify('تمت إضافة الباقة المخصصة إلى السلة') }} />} />
      <Route path="/ai-bouquet-designer" element={<AIDesignerConnected />} />
      <Route path="/cart" element={<Cart cart={cart} />} />
      <Route path="/checkout" element={<CheckoutConnected cart={cart} />} />
      <Route path="/track-order" element={<TrackOrder />} />
      <Route path="/favorites" element={<Favorites />} />
      <Route path="/account" element={<Account />} />
      <Route path="*" element={<NotFound />} />
    </Routes>
    <ChatFab />
    <Footer />
  </div></CatalogProvider>
}

function Announcement() { const { publicConfig } = useCatalog(); const settings = publicConfig.settings; const closed = settings.acceptingOrders === false || settings.temporaryClosed === true; const announcement = typeof settings.announcement === 'string' && settings.announcement.trim() ? settings.announcement : closed ? 'المتجر مغلق مؤقتاً لاستقبال الطلبات' : 'هديتك المميزة تبدأ من هنا — توصيل داخل بغداد'; return <div className="announcement"><span><Zap size={14} fill="currentColor" /> {announcement}</span><span className="desktop-only">{closed ? 'سنعود قريباً' : 'الدفع عند الاستلام متاح حسب إعدادات المتجر'}</span></div> }
function Header({ menu, setMenu, cartCount }: { menu: boolean; setMenu: (v: boolean) => void; cartCount: number }) {
  const { publicConfig } = useCatalog(); const settings = publicConfig.settings; const storeName = typeof settings.storeName === 'string' && settings.storeName.trim() ? settings.storeName : 'الأساس'; const storeLogo = configuredImage(settings.logoUrl, logo)
  return <header className="header"><div className="header-inner">
    <button className="mobile-menu icon-btn" onClick={() => setMenu(!menu)} aria-label="فتح القائمة">{menu ? <X /> : <Menu />}</button>
    <Link to="/" className="brand"><img src={storeLogo} alt={`${storeName} AL ASAS`} /><span><b>{storeName}</b><small>من الأساس تبدأ الفكرة</small></span></Link>
    <nav className={`main-nav ${menu ? 'open' : ''}`}>
      <NavLink to="/" end>الرئيسية</NavLink><NavLink to="/shop">تسوّق</NavLink><NavLink to="/send-a-gift">أرسل هدية</NavLink><NavLink to="/design-your-bouquet">صمّم باقتك</NavLink><NavLink to="/shop?category=هدايا التخرج">المناسبات</NavLink><NavLink to="/ai-bouquet-designer" className="nav-ai"><Sparkles size={15} /> مساعد الباقة</NavLink>
    </nav>
    <div className="header-actions"><button className="icon-btn desktop-only" aria-label="بحث"><Search /></button><Link to="/favorites" className="icon-btn desktop-only" aria-label="المفضلة"><Heart /></Link><Link to="/account" className="icon-btn desktop-only" aria-label="الحساب"><CircleUserRound /></Link><Link to="/cart" className="cart-btn"><ShoppingBag size={19} /><span>السلة</span>{cartCount > 0 && <em>{cartCount}</em>}</Link></div>
  </div></header>
}

function Home({ onAdd }: { onAdd: (productId: string) => void }) {
  const { realProducts, categories: catalogCategories, publicConfig } = useCatalog(); const homepage = publicConfig.homepage; const settings = publicConfig.settings; const heroTitle = typeof homepage.heroTitle === 'string' && homepage.heroTitle.trim() ? homepage.heroTitle : 'هديتك تبدأ من وردة'; const heroDescription = typeof homepage.heroDescription === 'string' && homepage.heroDescription.trim() ? homepage.heroDescription : 'باقات وهدايا مختارة بعناية، تصل بلمسة تليق بالمناسبة.'; const configuredHero = homepage.heroPosterUrl || homepage.bannerImage; const adminHeroLooksFloral = typeof configuredHero === 'string' && /rose|flower|floral|bouquet|ورد|زهور|باقة/i.test(configuredHero) && !/alasas|logo|ai-avatar/i.test(configuredHero); const heroImage = adminHeroLooksFloral ? configuredImage(configuredHero, floralFallback) : floralFallback; const heroMedia = typeof homepage.heroMediaUrl === 'string' && /^(https?:\/\/|\/)/i.test(homepage.heroMediaUrl.trim()) && adminHeroLooksFloral ? homepage.heroMediaUrl.trim() : ''; const heroMediaType = homepage.heroMediaType === 'video' && homepage.heroVideoEnabled !== false && homepage.heroVideoEnabled !== 'false' ? 'video' : 'image'; const heroPositionDesktop = typeof homepage.heroObjectPositionDesktop === 'string' && homepage.heroObjectPositionDesktop.trim() ? homepage.heroObjectPositionDesktop : 'center'; const heroPositionTablet = typeof homepage.heroObjectPositionTablet === 'string' && homepage.heroObjectPositionTablet.trim() ? homepage.heroObjectPositionTablet : heroPositionDesktop; const heroPositionMobile = typeof homepage.heroObjectPositionMobile === 'string' && homepage.heroObjectPositionMobile.trim() ? homepage.heroObjectPositionMobile : heroPositionTablet; const featuredCategory = typeof homepage.featuredCategory === 'string' ? homepage.featuredCategory : ''; const featuredProducts = (featuredCategory ? realProducts.filter(product => product.category === featuredCategory && product.featured) : realProducts.filter(product => product.featured)).slice(0, 4); const offerProducts = realProducts.filter(product => Boolean(product.compareAtPrice || product.discountPercent)).slice(0, 4); const bouquetProducts = realProducts.filter(product => /ورد|باقة|باقات/i.test(`${product.category} ${product.flowerType || ''}`)).slice(0, 4); const giftProducts = realProducts.filter(product => /هدية|هدايا|إضافة|إضافات|بوكس/i.test(product.category)).slice(0, 4); const occasionNames = [...new Set(realProducts.flatMap(product => product.occasions || []))].slice(0, 6); const deliveryText = typeof settings.deliveryInfo === 'string' && settings.deliveryInfo.trim() ? settings.deliveryInfo : ''
  return <main>
     {catalogCategories.length > 0 ? <section className="store-categories section compact-top"><div className="container"><SectionHeading title="تسوّق حسب النوع" action="استكشف الكل" href="/shop" /><div className="category-grid">{catalogCategories.slice(0, 6).map(([title, sub, img], i) => <Link className={`category-card cat-${i}`} to={`/shop?category=${encodeURIComponent(title)}`} key={title}><img src={configuredImage(img, floralFallback)} alt="" /><div className="category-overlay"><span>{String(i + 1).padStart(2, '0')}</span><h3>{title}</h3><p>{sub}</p></div></Link>)}</div></div></section> : <section className="store-categories section compact-top"><div className="container"><EmptyState title="الأقسام قيد الإعداد" text="ستظهر أقسام المتجر هنا فور نشرها من لوحة الإدارة." link="/shop" /></div></section>}
     <section className={`hero section ${(homepage.heroFullWidth === true || homepage.heroFullWidth === 'true') ? 'hero-full-width' : ''}`}><div className="container hero-grid"><div className="hero-copy"><span className="hero-kicker">متجر ورد وهدايا</span><h1>{heroTitle.split('\n').map((line, index) => <React.Fragment key={line}>{index > 0 && <br />}<i>{line}</i></React.Fragment>)}</h1><p>{heroDescription}</p><div className="hero-actions"><Link to="/send-a-gift" className="btn btn-dark">أرسل هدية <Send size={18} /></Link><Link to="/design-your-bouquet" className="btn btn-light">صمّم باقتك <Palette size={18} /></Link></div></div><div className="hero-visual"><div className="hero-image-wrap" style={{ '--hero-position-desktop': heroPositionDesktop, '--hero-position-tablet': heroPositionTablet, '--hero-position-mobile': heroPositionMobile } as React.CSSProperties}>{heroMediaType === 'video' && heroMedia ? <video className="hero-media" src={heroMedia} poster={heroImage} autoPlay muted loop playsInline preload="metadata" aria-label="وسائط Hero" onError={event => { event.currentTarget.style.display = 'none' }} /> : null}<img className={heroMediaType === 'video' && heroMedia ? 'hero-fallback' : ''} src={heroImage} alt="ورد من متجر المتجر" /></div></div></div></section>
     {occasionNames.length > 0 && <section className="section occasion-section"><div className="container"><SectionHeading title="تسوّق حسب المناسبة" action="كل المناسبات" href="/shop" /><div className="occasion-list">{occasionNames.map(name => <Link key={name} to={`/shop?occasion=${encodeURIComponent(name)}`}><span>✦</span>{name}<ArrowLeft size={15} /></Link>)}</div></div></section>}
     <HomeProductShelf title="باقات الورد" products={bouquetProducts} onAdd={onAdd} emptyText="ستظهر باقات الورد هنا بعد نشر المنتجات من Firebase." />
     <HomeProductShelf title="الهدايا والإضافات" products={giftProducts} onAdd={onAdd} emptyText="ستظهر الهدايا والإضافات هنا بعد نشرها من لوحة الإدارة." />
     <section className="editorial section gifting-cta"><div className="container editorial-grid"><div className="editorial-image"><img src={heroImage} alt="أرسل هدية" /></div><div className="editorial-copy"><h2>خلّي الهدية تحچي<br /><i>عن شعورك.</i></h2><p>أرسل تفاصيل المناسبة، وخلي فريق المتجر يرتبها من المنتجات المنشورة فعلياً.</p><div className="hero-actions"><Link to="/send-a-gift" className="btn btn-dark">أرسل هدية <Send size={17} /></Link></div></div></div></section>
     <section className="builder-cta section"><div className="container builder-cta-inner"><div><span className="hero-kicker">اختيارك، بطريقتك</span><h2>صمّم باقتك على ذوقك.</h2><p>اختَر الخيارات المتاحة من إعدادات المتجر، وشوف ملخص باقتك قبل الإرسال.</p></div><Link to="/design-your-bouquet" className="btn btn-light">ابدأ التصميم <Palette size={17} /></Link></div></section>
     <HomeProductShelf title="المنتجات المميزة" products={featuredProducts} onAdd={onAdd} emptyText="لا توجد منتجات مميزة منشورة حالياً." />
     <HomeProductShelf title="العروض" products={offerProducts} onAdd={onAdd} emptyText="لا توجد عروض منشورة حالياً." />
     <section className="delivery-section section"><div className="container delivery-card"><Truck size={27} /><div><h2>معلومات التوصيل</h2><p>{deliveryText || 'تظهر تفاصيل التوصيل هنا بعد إعدادها من لوحة الإدارة.'}</p></div><Link to="/shop" className="text-link">تصفّح المنتجات <ArrowLeft size={16} /></Link></div></section>
    <section className="ai-banner section"><div className="container ai-grid"><div><div className="eyebrow lime-eyebrow"><Sparkles size={15} /> ميزة الأساس</div><h2>احچي ويانه عن باقتك...<br /><i>وخلي الباقي علينا.</i></h2><p>وصف بسيط منك، وتصوّر أولي للباقة اللي ببالك. مساعد تجريبي يفهم اللهجة العراقية ويوصلك لتصميم واضح.</p><Link to="/ai-bouquet-designer" className="btn btn-lime">ابدأ تصميم باقتك <ArrowLeft size={18} /></Link></div><div className="chat-preview"><div className="chat-top"><RoseAvatar /><div><b>مساعد تنسيق الباقات</b><small><span /> متاح الآن</small></div><MoreDots /></div><div className="bubble assistant">هلا بيك! شنو المناسبة اللي نرتب إلها اليوم؟</div><div className="bubble user">أريد باقة تخرج ناعمة بحدود ٣٠ ألف</div><div className="suggestions"><span>تغليف أسود</span><span>ورد وردي</span><span>أضيف بطاقة</span></div></div></div></section>
  </main>
}

function HomeProductShelf({ title, products, onAdd, emptyText }: { title: string; products: Product[]; onAdd: (productId: string) => void; emptyText: string }) { return <section className="section home-shelf"><div className="container"><SectionHeading title={title} action="عرض الكل" href="/shop" />{products.length ? <div className="product-grid">{products.map(product => <ProductCard key={product.id} product={product} onAdd={onAdd} />)}</div> : <div className="catalog-empty"><Package size={25} /><p>{emptyText}</p><Link to="/shop" className="btn btn-light">استكشف المتجر</Link></div>}</div></section> }

function SectionHeading({ eyebrow, title, action, href }: { eyebrow?: string; title: string; action?: string; href?: string }) { return <div className="section-heading"><div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h2>{title}</h2></div>{action && href && <Link className="text-link" to={href}>{action} <ArrowLeft size={17} /></Link>}</div> }
function ProductCard({ product, onAdd }: { product: Product; onAdd: (productId: string) => void }) { const [fav, setFav] = useState(() => readFavoriteIds().includes(product.id)); const { live } = useCatalog(); const canOrder = live && product.orderable !== false && product.demo !== true; useEffect(() => { const refresh = () => setFav(readFavoriteIds().includes(product.id)); window.addEventListener('alasas-favorites-changed', refresh); return () => window.removeEventListener('alasas-favorites-changed', refresh) }, [product.id]); return <article className="product-card"><div className="product-image"><Link to={`/product/${product.id}`}><img src={product.image} alt={product.name} /></Link>{product.badge && <span className="product-badge">{product.badge}</span>}{product.discountPercent ? <span className="product-badge">-{product.discountPercent}%</span> : null}<button className={`fav-btn ${fav ? 'active' : ''}`} onClick={() => setFav(toggleFavoriteId(product.id))} aria-label={fav ? 'إزالة من المفضلة' : 'إضافة إلى المفضلة'}><Heart size={17} fill={fav ? 'currentColor' : 'none'} /></button><button className="quick-add" disabled={!canOrder} onClick={() => canOrder && onAdd(product.id)}><Plus size={16} /> {product.demo ? 'غير متاح للطلب' : canOrder ? 'أضف للسلة' : 'متاح بعد النشر'}</button></div><div className="product-meta"><div><small>{product.demo ? 'منتج تجريبي' : product.category}</small><Link to={`/product/${product.id}`}><h3>{product.name}</h3></Link></div><div className="product-price">{product.compareAtPrice && <del>{money(product.compareAtPrice)}</del>} {money(product.price)}</div></div></article> }

function Shop({ onAdd }: { onAdd: (productId: string) => void }) { const { products: catalogProducts } = useCatalog(); const [params, setParams] = useSearchParams(); const [search, setSearch] = useState(''); const [category, setCategory] = useState(params.get('category') || 'الكل'); const [occasion, setOccasion] = useState(params.get('occasion') || 'الكل'); const [flowerType, setFlowerType] = useState(params.get('flowerType') || 'الكل'); const [minPrice, setMinPrice] = useState(''); const [maxPrice, setMaxPrice] = useState(''); const [onlyAvailable, setOnlyAvailable] = useState(false); const [onlyDiscounted, setOnlyDiscounted] = useState(false); const [onlyNew, setOnlyNew] = useState(false); const [onlyBestSeller, setOnlyBestSeller] = useState(false); const categories = ['الكل', ...Array.from(new Set(catalogProducts.map(product => product.category).filter(Boolean)))]; const occasions = ['الكل', ...Array.from(new Set(catalogProducts.flatMap(product => product.occasions || []).filter(Boolean)))]; const flowerTypes = ['الكل', ...Array.from(new Set(catalogProducts.map(product => product.flowerType).filter(Boolean) as string[]))]; const updateCategory = (value: string) => { setCategory(value); setParams(current => { if (value === 'الكل') current.delete('category'); else current.set('category', value); return current }, { replace: true }) }; const filtered = catalogProducts.filter(p => { const min = minPrice ? Number(minPrice) : 0; const max = maxPrice ? Number(maxPrice) : Number.POSITIVE_INFINITY; const discounted = Boolean(p.compareAtPrice && p.compareAtPrice > p.price) || Boolean(p.discountPercent && p.discountPercent > 0); const available = p.stock !== undefined && p.stock > 0; const isNew = p.isNew === true || p.badge === 'جديد'; const bestSeller = p.bestseller === true || p.badge === 'الأكثر طلباً'; return (category === 'الكل' || p.category === category) && (occasion === 'الكل' || p.occasions?.includes(occasion)) && (flowerType === 'الكل' || p.flowerType === flowerType) && p.name.includes(search) && (!minPrice || (Number.isFinite(min) && p.price >= min)) && (!maxPrice || (Number.isFinite(max) && p.price <= max)) && (!onlyAvailable || available) && (!onlyDiscounted || discounted) && (!onlyNew || isNew) && (!onlyBestSeller || bestSeller) }); return <main className="page"><div className="container"><div className="page-intro"><div><div className="eyebrow">المتجر</div><h1>كل الهدايا،<br /><i>بلمسة الأساس.</i></h1></div><p>تشكيلة مختارة من الزهور والهدايا للمناسبات التي تستحق أن تُحتفل.</p></div><div className="shop-toolbar"><div className="search-field"><Search size={18} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="ابحث عن باقة أو هدية..." /></div><div className="filter-scroll">{categories.map(c => <button className={category === c ? 'selected' : ''} onClick={() => updateCategory(c)} key={c}>{c}</button>)}</div><div className="shop-filters"><label>المناسبة<select value={occasion} onChange={e => setOccasion(e.target.value)}>{occasions.map(value => <option key={value}>{value}</option>)}</select></label><label>نوع الورد<select value={flowerType} onChange={e => setFlowerType(e.target.value)}>{flowerTypes.map(value => <option key={value}>{value}</option>)}</select></label><label>من<input inputMode="numeric" value={minPrice} onChange={e => setMinPrice(e.target.value.replace(/[^0-9]/g, ''))} placeholder="السعر الأدنى" /></label><label>إلى<input inputMode="numeric" value={maxPrice} onChange={e => setMaxPrice(e.target.value.replace(/[^0-9]/g, ''))} placeholder="السعر الأعلى" /></label><div className="filter-checks"><label><input type="checkbox" checked={onlyAvailable} onChange={e => setOnlyAvailable(e.target.checked)} /> متوفر</label><label><input type="checkbox" checked={onlyDiscounted} onChange={e => setOnlyDiscounted(e.target.checked)} /> خصم</label><label><input type="checkbox" checked={onlyNew} onChange={e => setOnlyNew(e.target.checked)} /> جديد</label><label><input type="checkbox" checked={onlyBestSeller} onChange={e => setOnlyBestSeller(e.target.checked)} /> الأكثر مبيعاً</label></div></div></div>{filtered.length ? <div className="product-grid shop-grid">{filtered.map(p => <ProductCard key={p.id} product={p} onAdd={onAdd} />)}</div> : <EmptyState title="ما لقينا نتائج" text="جرّب كلمة مختلفة أو امسح الفلتر." />}</div></main> }

function ProductPage({ onAdd }: { onAdd: (productId: string, quantity: number, options?: CartOptions) => void }) { const { products: catalogProducts, live } = useCatalog(); const { slug } = useParams(); const product = catalogProducts.find(p => p.id === slug); const [qty, setQty] = useState(1); const [packagingColor, setPackagingColor] = useState('أسود'); const [giftMessage, setGiftMessage] = useState(''); const [selectedAddOns, setSelectedAddOns] = useState<string[]>([]); const favoriteId = product?.id || ''; const [favorite, setFavorite] = useState(() => favoriteId ? readFavoriteIds().includes(favoriteId) : false); useEffect(() => { if (!favoriteId) return; const refresh = () => setFavorite(readFavoriteIds().includes(favoriteId)); window.addEventListener('alasas-favorites-changed', refresh); return () => window.removeEventListener('alasas-favorites-changed', refresh) }, [favoriteId]); if (!product) return <main className="page"><EmptyState title="المنتج غير متاح حالياً" text="جرّب تصفح متجرنا مرة أخرى." link="/shop" /></main>; const canOrder = live && product.orderable !== false && product.demo !== true; const colors = product.colors?.length ? product.colors : ['أسود', 'أبيض', 'كرافت', 'أوف وايت']; const toggleAddOn = (value: string) => setSelectedAddOns(current => current.includes(value) ? current.filter(item => item !== value) : [...current, value]); return <main className="page"><div className="container detail-grid"><ProductGallery product={product} /><div className="detail-copy"><Link to="/shop" className="back-link"><ArrowLeft size={16} /> العودة للمتجر</Link><div className="eyebrow">{product.demo ? 'منتج تجريبي' : product.category}</div><h1>{product.name}</h1><div className="detail-price">{money(product.price)}</div><p className="detail-description">{product.description} ننسّقها بعناية ونضيف بطاقة تهنئة مجانية حسب اختيارك.</p>{product.demo && <div className="demo-note">هذا منتج تجريبي للعرض فقط وغير متاح للطلب التجاري.</div>}<div className="option-box"><label>لون التغليف</label><div className="choice-grid">{colors.map(color => <button type="button" className={packagingColor === color ? 'choice selected' : 'choice'} onClick={() => setPackagingColor(color)} key={color}>{color}</button>)}</div></div>{product.addOns?.length ? <div className="option-box"><label>الإضافات المتاحة</label><div className="choice-grid">{product.addOns.map(addOn => <button type="button" className={selectedAddOns.includes(addOn) ? 'choice selected' : 'choice'} onClick={() => toggleAddOn(addOn)} key={addOn}>{selectedAddOns.includes(addOn) ? '✓ ' : '+ '}{addOn}</button>)}</div></div> : null}<div className="option-box"><label>أضف رسالة مجانية</label><textarea value={giftMessage} onChange={event => setGiftMessage(event.target.value)} placeholder="اكتب رسالتك هنا (اختياري)" /></div><div className="purchase-row"><div className="quantity"><button onClick={() => setQty(Math.max(1, qty - 1))}><Minus size={15} /></button><b>{qty}</b><button onClick={() => setQty(qty + 1)}><Plus size={15} /></button></div><button className="btn btn-dark grow" disabled={!canOrder} onClick={() => canOrder && onAdd(product.id, qty, { packaging: product.packaging, packagingColor, giftMessage, addOns: selectedAddOns })}>{product.demo ? 'غير متاح للطلب' : canOrder ? 'أضف للسلة' : 'متاح بعد نشر المنتج'} <ShoppingBag size={18} /></button><button className={`icon-btn bordered ${favorite ? 'active' : ''}`} aria-label={favorite ? 'إزالة من المفضلة' : 'إضافة إلى المفضلة'} onClick={() => setFavorite(toggleFavoriteId(product.id))}><Heart size={19} fill={favorite ? 'currentColor' : 'none'} /></button></div><div className="delivery-note"><Truck size={18} /><span><b>توصيل منسّق</b><small>نرتب موعد التسليم معك قبل التجهيز</small></span></div></div></div><div className="container related"><SectionHeading title="قد يعجبك أيضاً" action="عرض الكل" href="/shop" /><div className="product-grid">{catalogProducts.slice(4, 8).map(p => <ProductCard key={p.id} product={p} onAdd={id => onAdd(id, 1)} />)}</div></div></main> }
function ProductGallery({ product }: { product: Product }) { const images = Array.from(new Set([product.image, ...(product.imageUrls || [])])); const [selected, setSelected] = useState(images[0]); useEffect(() => setSelected(images[0]), [product.id, product.image, product.imageUrls?.join('|')]); return <div className="detail-gallery"><img src={selected} alt={product.name} />{images.length > 1 && <div className="detail-thumbnails" style={{ display: 'flex', gap: 8, marginTop: 10, overflowX: 'auto' }} aria-label="صور المنتج">{images.map((src, index) => <button type="button" className={selected === src ? 'selected' : ''} style={{ width: 64, height: 64, padding: 0, flex: '0 0 auto', background: '#fff', border: selected === src ? '2px solid #111' : '1px solid #dedbd2' }} key={`${src}-${index}`} onClick={() => setSelected(src)}><img style={{ width: '100%', height: '100%', objectFit: 'cover' }} src={src} alt={`${product.name} ${index + 1}`} /></button>)}</div>}<div className="gallery-caption"><span>AL ASAS / FLOWERS</span><span>{images.length > 1 ? `${images.length} صور من الكتالوج` : 'صورة المنتج من الكتالوج'}</span></div></div> }

function Designer({ onAdd }: { onAdd: () => void }) { const [flower, setFlower] = useState('ورد'); const [count, setCount] = useState(6); const [wrap, setWrap] = useState('أسود'); const [style, setStyle] = useState('ناعم'); const [addons, setAddons] = useState<string[]>([]); const price = 16000 + count * 3200 + (wrap === 'فاخر' ? 6000 : 0) + (style === 'فاخر' ? 5000 : 0) + addons.length * 3500; const toggle = (x: string) => setAddons(a => a.includes(x) ? a.filter(v => v !== x) : [...a, x]); return <main className="page"><div className="container"><div className="designer-header"><div><div className="eyebrow">مساحة التصميم</div><h1>صمّم باقتك،<br /><i>بطريقتك.</i></h1></div><p>كل خيار يقرّبك من الهدية التي تخيلتها. السعر يتحدث معك مباشرة.</p></div><div className="designer-layout"><div className="designer-form"><Step n="01" title="اختَر نوع الورد"><div className="choice-grid">{['ورد', 'توليب', 'ليلي', 'دوار الشمس', 'مشكل'].map(x => <button className={flower === x ? 'choice selected' : 'choice'} onClick={() => setFlower(x)} key={x}><span className="flower-icon">✦</span>{x}</button>)}</div></Step><Step n="02" title="حدّد الكمية"><div className="range-row"><input type="range" min="3" max="15" value={count} onChange={e => setCount(Number(e.target.value))} /><b>{count} <small>وردة</small></b></div></Step><Step n="03" title="اختَر التغليف"><div className="choice-grid wraps">{['أسود', 'أبيض', 'أوف وايت', 'كرافت', 'فاخر'].map(x => <button className={wrap === x ? 'choice selected' : 'choice'} onClick={() => setWrap(x)} key={x}><span className={`wrap-swatch ${x}`} />{x}</button>)}</div></Step><Step n="04" title="اللمسات الأخيرة"><div className="choice-grid addons">{['بطاقة تهنئة', 'شوكولاتة', 'شريط ساتان', 'دبدوب صغير'].map(x => <button className={addons.includes(x) ? 'choice selected' : 'choice'} onClick={() => toggle(x)} key={x}><span>{addons.includes(x) ? <Check size={16} /> : <Plus size={16} />}</span>{x}</button>)}</div></Step></div><aside className="design-summary"><div className="preview-bouquet"><img src={image('photo-1548094971-2e4a2a1f13a4', 800, 900)} alt="معاينة الباقة" /><span>معاينة تقريبية</span></div><div className="summary-content"><div className="summary-label"><span>ملخص باقتك</span><Sparkles size={16} /></div><h3>{count} وردة {flower}</h3><p>تغليف {wrap} · تنسيق {style}</p><div className="summary-line"><span>الباقة</span><b>{money(16000 + count * 3200)}</b></div><div className="summary-line"><span>الإضافات</span><b>{money(addons.length * 3500)}</b></div><div className="summary-total"><span>السعر التقريبي</span><b>{money(price)}</b></div><button className="btn btn-dark full" onClick={onAdd}>أضف التصميم للسلة <ShoppingBag size={18} /></button><p className="disclaimer">الصورة لغرض المعاينة التقريبية، وقد يختلف التنسيق الفعلي حسب توفر الورد والتغليف.</p></div></aside></div></div></main> }
function Step({ n, title, children }: { n: string; title: string; children: React.ReactNode }) { return <section className="step"><div className="step-title"><span>{n}</span><h2>{title}</h2></div>{children}</section> }

function configuredAssistantAvatar(value: unknown) { return typeof value === 'string' && /^https?:\/\//i.test(value.trim()) ? value.trim() : '' }
function AIDesignerConnected() {
  const { publicConfig, products } = useCatalog(); const config = publicConfig.aiAssistant; const avatarUrl = config.assistantAvatarEnabled !== false && config.assistantAvatarEnabled !== 'false' ? configuredAssistantAvatar(config.assistantAvatarUrl) : ''; const enabled = config.enabled !== false; const welcome = typeof config.welcomeMessage === 'string' && config.welcomeMessage.trim().length > 0 ? config.welcomeMessage : 'هلا بيك! احچيلي عن المناسبة والميزانية واللون اللي تفضله.'; const configuredChips = Array.isArray(config.packageOptions) ? config.packageOptions.filter((item): item is string => typeof item === 'string' && item.trim().length > 0).slice(0, 6) : []; const chips = configuredChips.length ? configuredChips : ['تخرج', 'عيد ميلاد', 'ورد أبيض']; const [messages, setMessages] = useState<Array<{ role: 'assistant' | 'user'; text: string }>>([{ role: 'assistant', text: welcome }]); const [input, setInput] = useState(''); const [suggestion, setSuggestion] = useState<Product | null>(null)
  useEffect(() => { setMessages(current => current.length === 1 && current[0].role === 'assistant' ? [{ role: 'assistant', text: welcome }] : current) }, [welcome])
  const send = () => { if (!enabled || !input.trim()) return; const text = input.trim().toLowerCase(); const match = products.find(product => `${product.name} ${product.category} ${product.flowerType || ''} ${(product.occasions || []).join(' ')}`.toLowerCase().includes(text)) || products.find(product => product.occasions?.some(occasion => text.includes(occasion.toLowerCase()))) || products.find(product => product.orderable && !product.demo) || null; setSuggestion(match); setMessages(current => [...current, { role: 'user', text: input.trim() }, { role: 'assistant', text: match ? `وجدت في الكتالوج: ${match.name} بسعر ${money(match.price)}. تحقق من التوفر والسعر النهائي في المتجر.` : 'لا توجد مطابقة منشورة في الكتالوج حالياً. جرّب تغيير المناسبة أو اللون.' }]); setInput('') }
  if (!enabled) return <main className="page"><div className="container narrow"><EmptyState title="المساعد غير متاح حالياً" text="يمكنك تصفح المنتجات أو التواصل مع المتجر." link="/shop" /></div></main>
  return <main className="page ai-page"><div className="container"><div className="ai-heading"><div><h1>احچي ويانه عن باقتك،<br /><i>ونرتبها سوا.</i></h1></div><span className="demo-pill">اقتراحات من الكتالوج · لا يوجد اتصال AI خارجي</span></div><div className="ai-workspace"><section className="chat-panel"><div className="chat-header"><RoseAvatar url={avatarUrl} /><div><b>{String(config.name || 'مساعد تنسيق الباقات')}</b><small><span /> اقتراحات أولية حسب الكتالوج المنشور</small></div></div><div className="messages">{messages.map((m, i) => <div className={`message-row ${m.role}`} key={i}><div className="message">{m.text}</div></div>)}</div><div className="quick-chips">{chips.map(x => <button type="button" onClick={() => setInput(x)} key={x}>{x}</button>)}</div><div className="chat-input"><input value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && send()} placeholder="المناسبة، الميزانية، اللون أو نوع الهدية..." /><button type="button" onClick={send} aria-label="إرسال"><Send size={18} /></button></div></section><aside className="ai-summary"><div className="summary-label"><span>اقتراح من الكتالوج</span></div>{suggestion ? <><div className="ai-preview"><img src={suggestion.image} alt={suggestion.name} /><div>{suggestion.name}</div></div><div className="spec-list"><div><span>القسم</span><b>{suggestion.category}</b></div><div><span>السعر المنشور</span><b>{money(suggestion.price)}</b></div></div><Link className="btn btn-lime full" to={`/product/${suggestion.id}`}>فتح المنتج <ArrowLeft size={18} /></Link></> : <p className="disclaimer">أخبر المساعد بالمناسبة أو اللون ليبحث في منتجات Firebase المنشورة.</p>}<Link className="btn btn-dark full" to="/design-your-bouquet">الانتقال لتصميم الباقة <Palette size={18} /></Link><p className="disclaimer">الاقتراح لا يحجز منتجاً ولا ينشئ طلباً.</p></aside></div></div></main>
}

function Cart({ cart }: { cart: CartState }) {
  const { products: catalogProducts, giftConfig, live } = useCatalog()
  const lines = cart.items.map(line => ({ line, product: catalogProducts.find(product => product.id === line.productId) })).filter(item => item.product)
  const missing = cart.items.filter(line => !catalogProducts.some(product => product.id === line.productId))
  const lineUnitPrice = (line: CartLine, product: Product) => {
    const options = line.gifting?.optionIds || {}
    const optionPrice = Object.entries(options).reduce((sum, [group, id]) => sum + ((((giftConfig[group as keyof GiftConfig] as Array<{ id: string; price: number }> | undefined) || []).find(item => item.id === id)?.price) || 0), 0)
    const addonPrice = (line.gifting?.addonIds || []).reduce((sum, id) => sum + (giftConfig.addons.find(item => item.id === id)?.price || 0), 0)
    const cardPrice = line.gifting?.cardId ? (giftConfig.cards.find(item => item.id === line.gifting?.cardId)?.price || 0) : 0
    return product.price + optionPrice + addonPrice + cardPrice
  }
  const subtotal = lines.reduce((sum, item) => sum + lineUnitPrice(item.line, item.product as Product) * item.line.quantity, 0)
  return <main className="page"><div className="container narrow"><div className="page-intro compact"><div><div className="eyebrow">سلة الهدايا</div><h1>جاهزة <i>للمسة الأخيرة؟</i></h1></div><p>{cart.count ? `عندك ${cart.count} ${cart.count === 1 ? 'منتج' : 'منتجات'} في السلة.` : 'سلتك تنتظر أول إضافة.'}</p></div>{cart.count ? <div className="cart-layout"><div className="cart-items">{!live && <p className="demo-note">الكتالوج الحالي للمعاينة فقط؛ لا يمكن إنشاء طلب حتى ينشر المتجر منتجاته وبيانات التوصيل.</p>}{missing.map(line => <div className="cart-item" key={line.lineId}><div><small>منتج غير متاح في الكتالوج الحالي</small><h3>{line.productId}</h3><button className="text-link" onClick={() => cart.remove(line.lineId)}>إزالة من السلة</button></div></div>)}{lines.map(({ line, product }) => product && <div className="cart-item" key={line.lineId}><img src={line.card?.image || product.image} alt="" /><div><small>{product.category}</small><h3>{product.name}</h3><p>{line.gifting?.optionIds && Object.keys(line.gifting.optionIds).length ? `تخصيصات: ${Object.values(line.gifting.optionIds).join('، ')}` : line.packagingColor ? `لون التغليف: ${line.packagingColor}` : line.packaging || 'التغليف حسب المنتج'}{line.gifting?.addonIds?.length ? ` · هدايا إضافية: ${line.gifting.addonIds.length}` : ''}{line.card ? ` · الكارت: ${line.card.text}` : ''}{line.card?.message || line.giftMessage ? ' · توجد رسالة' : ''}</p>{line.card?.message && <blockquote className="cart-message">{line.card.message}</blockquote>}<div className="quantity"><button onClick={() => cart.setQuantity(line.lineId, line.quantity - 1)}><Minus size={14} /></button><b>{line.quantity}</b><button onClick={() => cart.setQuantity(line.lineId, line.quantity + 1)}><Plus size={14} /></button></div><button className="text-link" onClick={() => cart.remove(line.lineId)}>إزالة</button></div><strong>{money(lineUnitPrice(line, product) * line.quantity)}</strong></div>)}</div><aside className="cart-summary"><h3>ملخص الطلب</h3><div><span>المجموع الفرعي</span><b>{money(subtotal)}</b></div><div><span>التوصيل</span><b>يُحسب عند التحقق</b></div><hr /><div className="total"><span>الإجمالي المبدئي</span><b>{money(subtotal)}</b></div>{live && !missing.length && <Link to="/checkout" className="btn btn-dark full">متابعة الطلب <ArrowLeft size={18} /></Link>}<Link to="/shop" className="text-link center">متابعة التسوق</Link></aside></div> : <EmptyState title="السلة فارغة حالياً" text="خلّينا نختار هدية تترك أثر." link="/shop" />}</div></main>
}
function Checkout({ cart }: { cart: CartState }) {
  const { products: catalogProducts, live } = useCatalog()
  const [customerName, setCustomerName] = useState('')
  const [phone, setPhone] = useState('')
  const [recipientName, setRecipientName] = useState('')
  const [recipientPhone, setRecipientPhone] = useState('')
  const [province, setProvince] = useState('بغداد')
  const [district, setDistrict] = useState('')
  const [address, setAddress] = useState('')
  const [deliveryAt, setDeliveryAt] = useState('')
  const [giftMessage, setGiftMessage] = useState('')
  const [busy, setBusy] = useState(false)
  const [feedback, setFeedback] = useState('')
  const [created, setCreated] = useState<{ orderId: string; total: number; paymentStatus?: string } | null>(null)
  const availableItems = cart.items.filter(item => catalogProducts.some(product => product.id === item.productId && product.demo !== true && product.orderable !== false))
  const submit = async (event: React.FormEvent) => {
    event.preventDefault(); setFeedback('')
    if (!live || !availableItems.length || availableItems.length !== cart.items.length) { setFeedback('الطلب غير جاهز: المنتجات التجريبية أو غير المنشورة غير قابلة للطلب.'); return }
    if (!district.trim()) { setFeedback('اكتب المنطقة أو القضاء للتأكد من أجور التوصيل.'); return }
    setBusy(true)
    try {
      if (!firebaseAuth.currentUser) await signInWithPopup(firebaseAuth, googleProvider)
      const createOrder = httpsCallable(firebaseFunctions, 'createOrder')
      const result = await createOrder({ items: availableItems, customerName, phone, recipientName, recipientPhone, province, district, address, deliveryAt, giftMessage, paymentMethodId: 'cash', idempotencyKey: crypto.randomUUID() })
      const data = result.data as { orderId: string; total: number; paymentStatus?: string }
      setCreated(data); cart.clear()
    } catch (error) {
      const code = typeof error === 'object' && error && 'code' in error ? String((error as { code?: string }).code).split('/').pop() : ''
      setFeedback(code === 'unauthenticated' ? 'يلزم تسجيل الدخول لإرسال الطلب.' : code === 'delivery-area-unconfigured' ? 'هذه المنطقة غير مهيأة للتوصيل بعد.' : code === 'payment-method-unavailable' ? 'طريقة الدفع غير مفعّلة حالياً.' : 'تعذر إرسال الطلب بأمان. راجع البيانات وحاول مرة أخرى.')
    } finally { setBusy(false) }
  }
  return <main className="page"><div className="container narrow"><div className="page-intro compact"><div><div className="eyebrow">إتمام الطلب</div><h1>باقي <i>كم تفصيلة.</i></h1></div></div>{created ? <div className="demo-card"><Check size={24} /><h3>تم تسجيل الطلب</h3><p>رقم الطلب: <b>{created.orderId}</b></p><p>الإجمالي المحسوب من الخادم: <b>{money(created.total)}</b></p><p>الحالة: {created.paymentStatus === 'UNPAID' ? 'الدفع عند الاستلام — غير مدفوع' : 'بانتظار مراجعة الدفع'}</p></div> : <div className="checkout-layout"><form className="checkout-form" onSubmit={submit}><div className="stepper"><span className="active">01 البيانات</span><span>02 التوصيل</span><span>03 المراجعة</span></div><label>الاسم الكامل<input required value={customerName} onChange={e => setCustomerName(e.target.value)} placeholder="مثال: زهراء محمد" /></label><label>رقم الهاتف<input required value={phone} onChange={e => setPhone(e.target.value)} placeholder="07xx xxx xxxx" /></label><label>اسم المستلم<input required value={recipientName} onChange={e => setRecipientName(e.target.value)} placeholder="اسم مستلم الهدية" /></label><label>هاتف المستلم<input required value={recipientPhone} onChange={e => setRecipientPhone(e.target.value)} placeholder="07xx xxx xxxx" /></label><label>المحافظة<select value={province} onChange={e => setProvince(e.target.value)}><option>بغداد</option><option>أربيل</option><option>البصرة</option></select></label><label>المنطقة أو القضاء<input required value={district} onChange={e => setDistrict(e.target.value)} placeholder="مثال: الكرادة" /></label><label>العنوان التفصيلي<textarea required value={address} onChange={e => setAddress(e.target.value)} placeholder="الشارع، أقرب نقطة دالة" /></label><label>موعد التسليم المطلوب<input required value={deliveryAt} onChange={e => setDeliveryAt(e.target.value)} placeholder="مثال: 2026-10-20 مساءً" /></label><label>رسالة البطاقة<textarea value={giftMessage} onChange={e => setGiftMessage(e.target.value)} placeholder="اختياري" /></label>{feedback && <p className="demo-note">{feedback}</p>}<button className="btn btn-dark full" disabled={busy}>{busy ? 'جارٍ التحقق والتسجيل...' : 'تأكيد وإرسال الطلب'} <ArrowLeft size={18} /></button></form><aside className="demo-card"><BadgePercent size={24} /><h3>{live ? 'طلب متصل بالمتجر' : 'عرض تجريبي'}</h3><p>{live ? 'سيتم احتساب السعر والتوصيل من إعدادات المتجر على الخادم.' : 'لم تُنشر منتجات المتجر بعد؛ لن يتم إرسال طلب حقيقي من هذه المعاينة.'}</p><div className="demo-order"><span>الدفع</span><b>الدفع عند الاستلام</b></div></aside></div>}</div></main>
}
function CheckoutReview({ cart }: { cart: CartState }) {
  const { products, giftConfig } = useCatalog()
  const lines = cart.items.map(item => ({ item, product: products.find(product => product.id === item.productId) })).filter(line => line.product)
  if (!lines.length) return null
  const lineUnitPrice = (item: CartLine, product: Product) => {
    const optionPrice = Object.entries(item.gifting?.optionIds || {}).reduce((sum, [group, id]) => sum + ((((giftConfig[group as keyof GiftConfig] as Array<{ id: string; price: number }> | undefined) || []).find(option => option.id === id)?.price) || 0), 0)
    const addonPrice = (item.gifting?.addonIds || []).reduce((sum, id) => sum + (giftConfig.addons.find(addon => addon.id === id)?.price || 0), 0)
    const cardPrice = item.gifting?.cardId ? (giftConfig.cards.find(card => card.id === item.gifting?.cardId)?.price || 0) : 0
    return product.price + optionPrice + addonPrice + cardPrice
  }
  const subtotal = lines.reduce((sum, line) => sum + lineUnitPrice(line.item, line.product as Product) * line.item.quantity, 0)
  return <section className="checkout-review"><div className="container narrow"><div className="checkout-review-card"><div><div className="eyebrow">مراجعة السلة</div><h2>طلبك قبل الإرسال</h2></div><div className="checkout-review-lines">{lines.map(({ item, product }) => <div className="checkout-review-line" key={item.lineId}><span>{product?.name} × {item.quantity}</span><b>{money(lineUnitPrice(item, product as Product) * item.quantity)}</b></div>)}</div><div className="checkout-review-total"><span>المجموع قبل التوصيل والخصم</span><b>{money(subtotal)}</b></div><p>تظهر أجور التوصيل حسب المنطقة داخل النموذج، ويعيد الخادم التحقق من السعر والخصم والتوفر عند الإرسال.</p></div></div></section>
}

function CheckoutConnected({ cart }: { cart: CartState }) {
  const { products: catalogProducts, live, publicConfig } = useCatalog()
  const [customerName, setCustomerName] = useState('')
  const [phone, setPhone] = useState('')
  const [recipientName, setRecipientName] = useState('')
  const [recipientPhone, setRecipientPhone] = useState('')
  const [province, setProvince] = useState('')
  const [district, setDistrict] = useState('')
  const [address, setAddress] = useState('')
  const [deliveryAt, setDeliveryAt] = useState('')
  const [giftMessage, setGiftMessage] = useState(() => cart.items.find(item => item.giftMessage)?.giftMessage || '')
  const [paymentMethodId, setPaymentMethodId] = useState('')
  const [transferReference, setTransferReference] = useState('')
  const [couponCode, setCouponCode] = useState('')
  const [busy, setBusy] = useState(false)
  const [feedback, setFeedback] = useState('')
  const [created, setCreated] = useState<{ orderId: string; total: number; paymentStatus?: string } | null>(null)
  const [whatsappUrl, setWhatsappUrl] = useState('')
  const availableItems = cart.items.filter(item => catalogProducts.some(product => product.id === item.productId))
  const provinceNames = Object.entries(publicConfig.delivery).filter(([, record]) => record && record.enabled !== false).map(([name]) => name)
  const paymentMethods = Object.values(publicConfig.paymentMethods).filter(method => !province || !method.provinces?.length || method.provinces.includes(province)).sort((a, b) => (a.order || 0) - (b.order || 0))
  const selectedProvince = publicConfig.delivery[province]
  const areas = selectedProvince?.areas || selectedProvince?.districts || {}
  const enabledAreas = Object.fromEntries(Object.entries(areas).filter(([, area]) => area && area.enabled !== false))
  const selectedArea = enabledAreas[district]
  const selectedPayment = paymentMethods.find(method => method.id === paymentMethodId)
  useEffect(() => { if (!province && provinceNames[0]) setProvince(provinceNames[0]) }, [province, provinceNames.join('|')])
  useEffect(() => { if (!paymentMethods.some(method => method.id === paymentMethodId)) setPaymentMethodId(paymentMethods[0]?.id || '') }, [paymentMethodId, paymentMethods.map(method => method.id).join('|')])
  useEffect(() => { if (district && !enabledAreas[district]) setDistrict('') }, [province, district, Object.keys(enabledAreas).join('|')])
  const createWhatsAppUrl = (orderId: string, total: number, method: PaymentMethodRecord) => {
    const whatsapp = typeof publicConfig.settings.whatsapp === 'string' ? publicConfig.settings.whatsapp.replace(/\D/g, '') : ''
    if (!whatsapp) return ''
    const productsText = availableItems.map(item => { const product = catalogProducts.find(candidate => candidate.id === item.productId); return `${product?.name || item.productId} × ${item.quantity}` }).join('\n')
    const packagingText = availableItems.map(item => { const product = catalogProducts.find(candidate => candidate.id === item.productId); return `${product?.name || item.productId}: ${item.packagingColor || item.packaging || product?.packaging || 'غير محدد'}` }).join('\n')
    const addOnsText = availableItems.map(item => { const product = catalogProducts.find(candidate => candidate.id === item.productId); return `${product?.name || item.productId}: ${item.addOns?.join('، ') || product?.addOns?.join('، ') || 'لا توجد'}` }).join('\n')
    const trackingUrl = `${window.location.origin}${import.meta.env.BASE_URL}#/track-order?order=${encodeURIComponent(orderId)}`
    const message = [`طلب جديد — ${String(publicConfig.settings.storeName || 'AL ASAS')}`, `رقم الطلب: ${orderId}`, `اسم الزبون: ${customerName}`, `رقم الهاتف: ${phone}`, `المستلم: ${recipientName}`, `المنتجات:\n${productsText}`, `التغليف:\n${packagingText}`, `الإضافات:\n${addOnsText}`, `رسالة الإهداء: ${giftMessage || 'لا توجد'}`, `المحافظة: ${province}`, `المنطقة: ${district}`, `العنوان: ${address}`, `موعد التوصيل: ${deliveryAt}`, `الإجمالي: ${money(total)}`, `طريقة الدفع: ${method.name}`, `مرجع التحويل: ${transferReference || 'لا يوجد'}`, `حالة الدفع: ${selectedPayment?.type === 'CASH' ? 'غير مدفوع' : 'بانتظار المراجعة'}`, `رابط الطلب: ${trackingUrl}`].join('\n')
    return `https://wa.me/${whatsapp}?text=${encodeURIComponent(message)}`
  }
  const submit = async (event: React.FormEvent) => {
    event.preventDefault(); setFeedback('')
    if (!live || !availableItems.length || availableItems.length !== cart.items.length) { setFeedback('الطلب غير جاهز: يجب أن تكون المنتجات منشورة في كتالوج المتجر.'); return }
    if (!selectedArea || !selectedPayment) { setFeedback('اختر محافظة ومنطقة وطريقة دفع مفعّلة من إعدادات المتجر.'); return }
    setBusy(true)
    try {
      if (!firebaseAuth.currentUser) await signInWithPopup(firebaseAuth, googleProvider)
      const createOrder = httpsCallable(firebaseFunctions, 'createOrder')
       const result = await createOrder({ items: availableItems.map(item => ({ ...item, ...(item.card ? { gifting: { ...(item.gifting || {}), cardId: item.card.id, cardMessage: item.card.message || giftMessage } } : {}), giftMessage: item.card?.message || item.giftMessage || giftMessage })), customerName, phone, recipientName, recipientPhone, province, district, address, deliveryAt, giftMessage, paymentMethodId, transferReference, couponCode, idempotencyKey: crypto.randomUUID() })
      const data = result.data as { orderId: string; total: number; paymentStatus?: string }
      setWhatsappUrl(createWhatsAppUrl(data.orderId, data.total, selectedPayment))
      setCreated(data)
      cart.clear()
    } catch (error) {
      const code = typeof error === 'object' && error && 'code' in error ? String((error as { code?: string }).code).split('/').pop() : ''
      setFeedback(code === 'unauthenticated' ? 'يلزم تسجيل الدخول لإرسال الطلب.' : code === 'delivery-area-unconfigured' ? 'هذه المنطقة غير مهيأة للتوصيل بعد.' : code === 'payment-method-unavailable' ? 'طريقة الدفع غير مفعّلة حالياً.' : code === 'discount-unavailable' ? 'انتهت صلاحية هذا الكوبون أو استُخدم الحد المسموح.' : 'تعذر إرسال الطلب بأمان. راجع البيانات وحاول مرة أخرى.')
    } finally { setBusy(false) }
  }
  return <main className="page"><div className="container narrow"><div className="page-intro compact"><div><div className="eyebrow">إتمام الطلب</div><h1>باقي <i>كم تفصيلة.</i></h1></div></div>{created ? <div className="demo-card"><Check size={24} /><h3>تم تسجيل الطلب</h3><p>رقم الطلب: <b>{created.orderId}</b></p><p>الإجمالي المحسوب من الخادم: <b>{money(created.total)}</b></p><p>الحالة: {created.paymentStatus === 'UNPAID' ? 'الدفع عند الاستلام — غير مدفوع' : 'بانتظار مراجعة الدفع'}</p><div className="form-actions"><Link className="btn btn-dark" to={`/track-order?order=${encodeURIComponent(created.orderId)}`}>تتبّع الطلب <ArrowLeft size={17} /></Link>{whatsappUrl && <a className="btn btn-lime" href={whatsappUrl} target="_blank" rel="noreferrer">تجهيز رسالة واتساب <Send size={17} /></a>}</div><p className="disclaimer">فتح واتساب لا يثبت إرسال الرسالة ولا موافقة الإدارة.</p></div> : <div className="checkout-layout"><form className="checkout-form" onSubmit={submit}><div className="stepper"><span className="active">01 البيانات</span><span>02 التوصيل</span><span>03 الدفع</span></div><label>الاسم الكامل<input required value={customerName} onChange={e => setCustomerName(e.target.value)} placeholder="مثال: زهراء محمد" /></label><label>رقم الهاتف<input required value={phone} onChange={e => setPhone(e.target.value)} placeholder="07xx xxx xxxx" /></label><label>اسم المستلم<input required value={recipientName} onChange={e => setRecipientName(e.target.value)} placeholder="اسم مستلم الهدية" /></label><label>هاتف المستلم<input required value={recipientPhone} onChange={e => setRecipientPhone(e.target.value)} placeholder="07xx xxx xxxx" /></label><label>المحافظة<select required value={province} onChange={e => { setProvince(e.target.value); setDistrict('') }}><option value="">اختر المحافظة</option>{provinceNames.map(name => <option key={name}>{name}</option>)}</select></label><label>المنطقة أو القضاء<select required value={district} onChange={e => setDistrict(e.target.value)}><option value="">اختر المنطقة</option>{Object.entries(enabledAreas).map(([name, area]) => <option key={name} value={name}>{name} — {money(area.price)}</option>)}</select></label><label>العنوان التفصيلي<textarea required value={address} onChange={e => setAddress(e.target.value)} placeholder="الشارع، أقرب نقطة دالة" /></label><label>موعد التسليم المطلوب<input required value={deliveryAt} onChange={e => setDeliveryAt(e.target.value)} placeholder="مثال: 2026-10-20 مساءً" /></label><label>طريقة الدفع<select required value={paymentMethodId} onChange={e => setPaymentMethodId(e.target.value)}><option value="">اختر طريقة الدفع</option>{paymentMethods.map(method => <option value={method.id} key={method.id}>{method.name}</option>)}</select></label>{selectedPayment && <div className="demo-note">{selectedPayment.recipient && <span>بيانات الاستلام: {selectedPayment.recipient}<br /></span>}{selectedPayment.bankName && <span>المصرف: {selectedPayment.bankName}<br /></span>}{selectedPayment.accountName && <span>صاحب الحساب: {selectedPayment.accountName}<br /></span>}{selectedPayment.accountNumber && <span>رقم الحساب: {selectedPayment.accountNumber}<br /></span>}{selectedPayment.iban && <span>IBAN: {selectedPayment.iban}<br /></span>}{selectedPayment.walletNumber && <span>محفظة زين كاش: {selectedPayment.walletNumber}<br /></span>}{selectedPayment.instructions}</div>}{selectedPayment && selectedPayment.type !== 'CASH' && <label>الرقم المرجعي للتحويل<input value={transferReference} onChange={e => setTransferReference(e.target.value)} placeholder="اختياري — لا يغني عن تحقق الإدارة" /></label>}<label>كود الخصم (اختياري)<input value={couponCode} onChange={e => setCouponCode(e.target.value.toUpperCase())} placeholder="مثال: SPRING10" autoComplete="off" /></label><label>رسالة البطاقة<textarea value={giftMessage} onChange={e => setGiftMessage(e.target.value)} placeholder="اختياري" /></label>{feedback && <p className="demo-note">{feedback}</p>}<button className="btn btn-dark full" disabled={busy || !selectedArea || !selectedPayment}>{busy ? 'جارٍ التحقق والتسجيل...' : 'تأكيد وإرسال الطلب'} <ArrowLeft size={18} /></button></form><aside className="demo-card"><BadgePercent size={24} /><h3>{live && paymentMethods.length ? 'طلب متصل بالمتجر' : 'Checkout محجوب مؤقتاً'}</h3><p>{live && paymentMethods.length ? 'السعر والتوصيل وطريقة الدفع مأخوذة من إعدادات المتجر؛ السعر النهائي يحسبه الخادم.' : 'لا توجد حالياً إعدادات نشر مكتملة للمنتجات والتوصيل والدفع؛ لن يتم إرسال طلب.'}</p><div className="demo-order"><span>أجرة التوصيل</span><b>{selectedArea ? money(selectedArea.price) : 'تُحسب بعد الاختيار'}</b></div></aside></div>}</div></main>
}
function TrackOrder() { const location = useLocation(); const [orderId, setOrderId] = useState(() => new URLSearchParams(location.search).get('order') || ''); const [order, setOrder] = useState<{ orderId: string; orderStatus: string; paymentStatus: string; total: number; deliveryAt: string; items: { name: string; quantity: number; lineTotal: number }[] } | null>(null); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const statuses = ['NEW', 'AWAITING_PAYMENT', 'PAYMENT_REVIEW', 'PAYMENT_CONFIRMED', 'APPROVED', 'PREPARING', 'READY_FOR_DELIVERY', 'OUT_FOR_DELIVERY', 'DELIVERED']; const labels: Record<string, string> = { NEW: 'تم استلام الطلب', AWAITING_PAYMENT: 'بانتظار التحويل', PAYMENT_REVIEW: 'بانتظار مراجعة الدفع', PAYMENT_CONFIRMED: 'تم تأكيد الدفع', APPROVED: 'تمت الموافقة', PREPARING: 'قيد التجهيز', READY_FOR_DELIVERY: 'جاهز للتوصيل', OUT_FOR_DELIVERY: 'خرج للتوصيل', DELIVERED: 'تم التسليم' }; const search = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setMessage(''); setOrder(null); try { if (!firebaseAuth.currentUser) await signInWithPopup(firebaseAuth, googleProvider); const call = httpsCallable(firebaseFunctions, 'getCustomerOrder'); const result = await call({ orderId: orderId.trim() }); setOrder(result.data as typeof order) } catch (error) { const code = typeof error === 'object' && error && 'code' in error ? String((error as { code?: string }).code).split('/').pop() : ''; setMessage(code === 'not-found' ? 'لم نعثر على طلب بهذا الرقم ضمن حسابك.' : 'تعذر قراءة الطلب. سجّل الدخول بالحساب الذي أنشأه وحاول مرة أخرى.') } finally { setBusy(false) } }; const currentIndex = order ? statuses.indexOf(order.orderStatus) : -1; return <main className="page"><div className="container narrow"><div className="centered-heading"><div className="eyebrow">تتبّع طلبك</div><h1>كل خطوة، <i>واضحة.</i></h1><p>أدخل رقم الطلب الذي أنشأته من حساب Google نفسه.</p></div><form className="track-search" onSubmit={search}><input required value={orderId} onChange={event => setOrderId(event.target.value)} placeholder="مثال: -P3rc..." /><button className="btn btn-dark" disabled={busy}>{busy ? 'جارٍ البحث...' : 'تتبّع'} <ArrowLeft size={17} /></button></form>{message && <p className="demo-note">{message}</p>}{order && <div className="tracking-card"><div className="tracking-head"><div><small>رقم الطلب</small><h3>{order.orderId}</h3></div><span className="status-pill">{labels[order.orderStatus] || order.orderStatus}</span></div><p>الإجمالي: <b>{money(order.total)}</b> · موعد التوصيل: <b>{order.deliveryAt || 'غير محدد'}</b></p><div className="timeline">{statuses.map((status, index) => <div className={`timeline-item ${index <= currentIndex ? 'done' : ''}`} key={status}><span>{index <= currentIndex ? <Check size={13} /> : index + 1}</span><div><b>{labels[status]}</b></div></div>)}</div><div className="demo-order"><span>حالة الدفع</span><b>{order.paymentStatus}</b></div><div className="record-list">{order.items.map((item, index) => <article className="record-row" key={`${item.name}-${index}`}><div><b>{item.name}</b><small>الكمية: {item.quantity}</small></div><strong>{money(item.lineTotal)}</strong></article>)}</div></div>}</div></main> }
function Favorites() { const { products: catalogProducts } = useCatalog(); const [ids, setIds] = useState<string[]>(readFavoriteIds); useEffect(() => { const refresh = () => setIds(readFavoriteIds()); window.addEventListener('alasas-favorites-changed', refresh); return () => window.removeEventListener('alasas-favorites-changed', refresh) }, []); const favorites = catalogProducts.filter(product => ids.includes(product.id)); return <main className="page"><div className="container"><div className="page-intro compact"><div><div className="eyebrow">مساحتك</div><h1>الأشياء التي <i>أحببتها.</i></h1></div><p>{favorites.length ? `${favorites.length} منتجات محفوظة محلياً أو متزامنة مع حسابك.` : 'احفظ الباقات التي تريد الرجوع إليها.'}</p></div>{favorites.length ? <div className="product-grid">{favorites.map(product => <ProductCard key={product.id} product={product} onAdd={() => undefined} />)}</div> : <EmptyState title="لا توجد مفضلات بعد" text="اضغط على القلب بجانب أي باقة لترجع لها بسهولة." link="/shop" />}<p className="demo-note">المفضلة تحفظ محلياً للزائر، وتُدمج تلقائياً مع حساب Google عند تسجيل الدخول.</p></div></main> }
function Account() { const [user, setUser] = useState(firebaseAuth.currentUser); const [orders, setOrders] = useState<{ orderId: string; orderStatus: string; paymentStatus: string; total: number; deliveryAt: string }[]>([]); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const refresh = async (current = firebaseAuth.currentUser) => { if (!current) return; setBusy(true); try { const result = await httpsCallable(firebaseFunctions, 'listCustomerOrders')({}); const data = result.data as { orders?: unknown }; setOrders(Array.isArray(data.orders) ? data.orders.filter((item): item is typeof orders[number] => Boolean(item && typeof item === 'object')) : []) } catch { setMessage('تعذر تحميل الطلبات الخاصة بالحساب.') } finally { setBusy(false) } }; useEffect(() => { const unsubscribe = onAuthStateChanged(firebaseAuth, current => { setUser(current); if (current) void refresh(current) }); return unsubscribe }, []); const signIn = async () => { setMessage(''); setBusy(true); try { const result = await signInWithPopup(firebaseAuth, googleProvider); setUser(result.user); await refresh(result.user) } catch { setMessage('لم يكتمل تسجيل الدخول.') } finally { setBusy(false) } }; const signInLocal = async () => { setMessage(''); setBusy(true); try { const result = await signInWithEmailAndPassword(firebaseAuth, localCustomerEmail, localCustomerPassword); setUser(result.user); await refresh(result.user) } catch { setMessage('تعذر تسجيل الدخول المحلي.') } finally { setBusy(false) } }; const logout = async () => { setBusy(true); setMessage(''); try { await signOut(firebaseAuth); setOrders([]); setUser(null); setMessage('تم تسجيل الخروج بأمان.'); } catch { setMessage('تعذر تسجيل الخروج. حاول مرة أخرى.'); } finally { setBusy(false) } }; return <main className="page"><div className="container account-grid"><aside className="account-side"><div className="profile-circle">{user?.displayName?.slice(0, 1) || 'ز'}</div><h3>{user?.displayName || 'زائر الأساس'}</h3><p>{user?.email || 'سجّل الدخول لمشاهدة طلباتك'}</p><nav><a className="active">نظرة عامة</a><Link to="/favorites">المفضلة ({readFavoriteIds().length})</Link><a>العناوين المحفوظة</a></nav></aside><section className="account-main"><div className="eyebrow">حسابك</div><h1>أهلاً بك، <i>{user?.displayName || 'زائرنا'}.</i></h1>{!user && <div className="demo-card"><p>سجّل الدخول بحساب Google نفسه الذي أنشأت به الطلبات.</p><button className="btn btn-dark" onClick={signIn} disabled={busy}>{busy ? 'جارٍ الدخول...' : 'تسجيل الدخول'}</button>{localEmulatorLogin && <><p className="demo-note">اختبار محلي فقط — لا يظهر في Production.</p><button className="btn btn-lime" onClick={signInLocal} disabled={busy}>{busy ? '...' : 'دخول Emulator المحلي'}</button></>}</div>}{user && <><div className="account-cards"><div><Package /><span>الطلبات</span><b>{orders.length}</b></div><div><Heart /><span>المفضلة</span><b>{readFavoriteIds().length}</b></div><div><Bell /><span>التذكيرات</span><b>0</b></div></div><div className="panel"><div className="form-actions"><h2>آخر الطلبات</h2><button type="button" className="btn btn-outline" onClick={logout} disabled={busy}>تسجيل الخروج</button></div>{busy && <p>جارٍ تحميل الطلبات...</p>}{orders.length ? <div className="record-list">{orders.map(order => <article className="record-row" key={order.orderId}><div><b>{order.orderId}</b><small>{order.orderStatus} · {order.paymentStatus} · {money(order.total)}</small></div><Link className="link-button" to={`/track-order?order=${encodeURIComponent(order.orderId)}`}>تتبّع</Link></article>)}</div> : !busy && <EmptyState title="لا توجد طلبات" text="ستظهر طلباتك هنا بعد تسجيلها." link="/shop" />}</div></>}{message && <p className="demo-note">{message}</p>}</section></div></main> }
function RoseAvatar({ url = '' }: { url?: string }) { const [failed, setFailed] = useState(false); useEffect(() => setFailed(false), [url]); const showImage = Boolean(url) && !failed; return <span className={`assistant-avatar${showImage ? ' has-image' : ''}`} role="img" aria-label="وردة المساعد الذكي">{showImage && <img className="assistant-avatar-image" src={url} alt="" onError={() => setFailed(true)} />}<span className="rose-petal rose-petal-a" /><span className="rose-petal rose-petal-b" /><span className="rose-petal rose-petal-c" /></span> }
function ChatFab() { const { publicConfig } = useCatalog(); const config = publicConfig.aiAssistant; const url = config.assistantAvatarEnabled !== false && config.assistantAvatarEnabled !== 'false' ? configuredAssistantAvatar(config.assistantAvatarUrl) : ''; return <Link to="/ai-bouquet-designer" className="chat-fab"><RoseAvatar url={url} /><span>صمّم مع المساعد</span></Link> }
function MoreDots() { return <span className="dots">•••</span> }
function EmptyState({ title, text, link }: { title: string; text: string; link?: string }) { return <div className="empty-state"><div><ShoppingBag size={24} /></div><h3>{title}</h3><p>{text}</p>{link && <Link className="btn btn-dark" to={link}>استكشف المتجر <ArrowLeft size={17} /></Link>}</div> }
function NotFound() { return <main className="page"><EmptyState title="هذه الصفحة غير موجودة" text="خلّينا نرجعك للمكان الصحيح." link="/" /></main> }
function Footer() { const { live, error } = useCatalog(); const catalogStatus = error ? 'تعذر الاتصال بكتالوج Firebase' : live ? 'الكتالوج متصل ببيانات المتجر' : 'عرض تجريبي — لا توجد منتجات منشورة في Firebase'; return <footer className="footer"><div className="container footer-grid"><div className="footer-brand"><Link to="/" className="brand"><img src={logo} alt="الأساس" /><span><b>الأساس</b><small>من الأساس تبدأ الفكرة</small></span></Link><p>منصة تجارة الزهور والهدايا التي تعطي كل متجر مساحته الخاصة.</p><div className="socials"><Instagram size={17} /><Phone size={17} /><span>واتساب</span></div></div><div><h4>تسوّق</h4><Link to="/shop">كل المنتجات</Link><Link to="/shop?category=باقات الورد">باقات الورد</Link><Link to="/shop?category=بوكسات الهدايا">بوكسات الهدايا</Link><Link to="/design-your-bouquet">صمّم باقتك</Link></div><div><h4>المساعدة</h4><Link to="/track-order">تتبّع الطلب</Link><Link to="/account">حسابي</Link><a>معلومات التوصيل</a><a>الأسئلة الشائعة</a></div><div className="footer-contact"><h4>خلّينا على تواصل</h4><p>نرتبها سوا، من أول فكرة لآخر لمسة.</p><a href="tel:+9647700000000"><Phone size={15} /> +964 770 000 0000</a><a href="mailto:hello@alasas.example"><Send size={15} /> hello@alasas.example</a></div></div><div className="container footer-bottom"><span>© 2024 AL ASAS · {catalogStatus}</span><span>صنع بـ <span className="lime-text">●</span> في العراق</span></div><div className="container footer-legal"><span>جميع الحقوق محفوظة لشركة الأساس للحلول البرمجية</span><span dir="ltr">Version 1.5.0</span></div></footer> }

function GiftSummary({ recipient, occasion, sender, hideSender, deliveryAt, message, total }: { recipient: string; occasion: string; sender: string; hideSender: boolean; deliveryAt: string; message: string; total?: number }) {
  return <aside className="gift-summary"><div className="eyebrow">معاينة آمنة</div><h2>تفاصيل الإهداء</h2><dl><div><dt>المستلم</dt><dd>{recipient || 'لم يُحدد بعد'}</dd></div><div><dt>المناسبة</dt><dd>{occasion || 'لم تُحدد بعد'}</dd></div><div><dt>المرسل</dt><dd>{hideSender ? 'مخفي عن المستلم' : sender || 'لم يُحدد بعد'}</dd></div><div><dt>موعد التوصيل</dt><dd>{deliveryAt || 'لم يُحدد بعد'}</dd></div></dl>{message && <blockquote>{message}</blockquote>}{typeof total === 'number' && <div className="gift-total"><span>التقدير الحالي</span><b>{money(total)}</b></div>}<p className="disclaimer">هذه معاينة محلية فقط. لا تُرسل بيانات المستلم ولا تُنشئ طلباً حتى تفعيل بوابة الطلب الآمنة.</p></aside>
}

function GiftPage() {
  const { giftConfig } = useCatalog(); const [recipient, setRecipient] = useState(''); const [recipientPhone, setRecipientPhone] = useState(''); const [occasion, setOccasion] = useState(''); const [province, setProvince] = useState(''); const [district, setDistrict] = useState(''); const [address, setAddress] = useState(''); const [deliveryAt, setDeliveryAt] = useState(''); const [sender, setSender] = useState(''); const [hideSender, setHideSender] = useState(false); const [message, setMessage] = useState(''); const [notes, setNotes] = useState('')
  const maxMessage = Number(giftConfig.settings.maxCardMessageLength || 300)
  const submit = (event: React.FormEvent) => { event.preventDefault(); window.alert('تمت المعاينة محلياً. استقبال الطلبات غير مفعّل حالياً.') }
  return <main className="page"><div className="container gift-page"><div className="page-intro"><div><div className="eyebrow">أرسل هدية</div><h1>خلّيها توصل <i>بإحساسك.</i></h1><p>جهّز تفاصيل الإهداء كاملة، ثم راجعها قبل أي خطوة لاحقة.</p></div><Link className="btn btn-lime" to="/bouquet-builder">صمّم باقتك <Palette size={17} /></Link></div><div className="gift-layout"><form className="checkout-form gift-form" onSubmit={submit}><h2>بيانات الإهداء</h2><div className="field-grid"><label>اسم المستلم<input required value={recipient} onChange={event => setRecipient(event.target.value)} maxLength={120} /></label><label>هاتف المستلم<input required value={recipientPhone} onChange={event => setRecipientPhone(event.target.value)} inputMode="tel" maxLength={30} /></label><label>المناسبة<select required value={occasion} onChange={event => setOccasion(event.target.value)}><option value="">اختر المناسبة</option>{giftConfig.occasions.map(item => <option key={item.id} value={item.label}>{item.label}</option>)}</select></label><label>المحافظة<input required value={province} onChange={event => setProvince(event.target.value)} maxLength={80} /></label><label>المنطقة<input required value={district} onChange={event => setDistrict(event.target.value)} maxLength={80} /></label><label>موعد التوصيل<input required type="datetime-local" value={deliveryAt} onChange={event => setDeliveryAt(event.target.value)} /></label></div><label>العنوان التفصيلي<textarea required value={address} onChange={event => setAddress(event.target.value)} maxLength={300} /></label><label>ملاحظات التوصيل<textarea value={notes} onChange={event => setNotes(event.target.value)} maxLength={300} /></label><div className="field-grid"><label>اسم المُرسل<input value={sender} onChange={event => setSender(event.target.value)} maxLength={120} disabled={hideSender} /></label><label className="check-field"><input type="checkbox" checked={hideSender} onChange={event => setHideSender(event.target.checked)} /> إخفاء اسم المُرسل عن المستلم</label></div><label>رسالة الإهداء<textarea value={message} onChange={event => setMessage(event.target.value.slice(0, maxMessage))} maxLength={maxMessage} /><small>{message.length}/{maxMessage}</small></label><div className="gift-actions"><button className="btn btn-dark" type="submit">مراجعة الإهداء <ArrowLeft size={17} /></button><Link className="btn btn-outline" to="/shop">اختيار منتج</Link></div></form><GiftSummary recipient={recipient} occasion={occasion} sender={sender} hideSender={hideSender} deliveryAt={deliveryAt} message={message} /></div></div></main>
}

function BouquetBuilder() {
  const { giftConfig } = useCatalog(); const [selected, setSelected] = useState<Record<string, string>>({}); const [addons, setAddons] = useState<string[]>([]); const [budget, setBudget] = useState('');
  const choose = (group: string, id: string) => setSelected(current => ({ ...current, [group]: id })); const selectedPrice = Object.entries(selected).reduce((sum, [group, id]) => sum + (((giftConfig[group as keyof GiftConfig] as Array<{ id: string; price: number }> | undefined) || []).find(item => item.id === id)?.price || 0), 0); const addonPrice = addons.reduce((sum, id) => sum + (giftConfig.addons.find(item => item.id === id)?.price || 0), 0); const card = giftConfig.cards[0]; const total = selectedPrice + addonPrice + (card?.price || 0);
  const groups: Array<[string, string, keyof GiftConfig]> = [['نوع الورد', 'flowerTypes', 'flowerTypes'], ['لون الورد', 'flowerColors', 'flowerColors'], ['عدد الورود', 'stemCounts', 'stemCounts'], ['نوع التغليف', 'wrappings', 'wrappings'], ['لون التغليف', 'wrappingColors', 'wrappingColors'], ['نوع الشريط', 'ribbons', 'ribbons']];
  return <main className="page"><div className="container gift-page"><div className="page-intro"><div><div className="eyebrow">مصمم الباقات</div><h1>صمّم باقتك <i>خطوة خطوة.</i></h1><p>الأسعار والخيارات المعروضة تأتي من إعدادات المتجر المنشورة. لا توجد صورة تركيبية تدّعي واقعية لم تُصوّر.</p></div><Link className="btn btn-outline" to="/send-a-gift">إرسال كهدية <Send size={17} /></Link></div><div className="builder-layout"><section className="builder-panel">{groups.map(([label, key, configKey]) => <fieldset className="builder-step" key={key}><legend>{label}</legend><div className="choice-grid">{((giftConfig[configKey] as Array<{ id: string; label: string; price: number; image?: string }>) || []).map(item => <button type="button" className={`choice ${selected[key] === item.id ? 'selected' : ''}`} onClick={() => choose(key, item.id)} key={item.id}>{item.image && <img src={item.image} alt="" />}{item.label}<small>{item.price ? `+ ${money(item.price)}` : 'بدون إضافة'}</small></button>)}</div>{!((giftConfig[configKey] as unknown[]) || []).length && <p className="demo-note">لا توجد خيارات منشورة من المتجر بعد.</p>}</fieldset>)}<fieldset className="builder-step"><legend>الإضافات</legend><div className="choice-grid">{giftConfig.addons.map(item => <button type="button" className={`choice ${addons.includes(item.id) ? 'selected' : ''}`} onClick={() => setAddons(current => current.includes(item.id) ? current.filter(id => id !== item.id) : [...current, item.id])} key={item.id}>{item.name}<small>+ {money(item.price)}</small></button>)}</div></fieldset><label className="field budget-field"><span>ميزانيتك (اختياري)</span><input type="number" min="0" value={budget} onChange={event => setBudget(event.target.value)} placeholder="بالدينار العراقي" /></label></section><aside className="builder-summary"><div className="builder-preview"><span>معاينة العناصر المختارة</span><strong>{Object.keys(selected).length ? 'اختياراتك جاهزة للمراجعة' : 'اختر عناصر الباقة'}</strong><small>هذه معاينة للخيارات وليست صورة واقعية لتركيبة نهائية.</small></div><GiftSummary recipient="" occasion="" sender="" hideSender={false} deliveryAt="" message="" total={total} /><button type="button" className="btn btn-dark full" onClick={() => window.alert('تم حفظ المعاينة محلياً فقط. استقبال الطلبات غير مفعّل حالياً.')}>مراجعة الباقة <ArrowLeft size={17} /></button></aside></div></div></main>
}

function GiftSummaryV2({ product, gift, card, recipient, occasion, sender, hideSender, deliveryAt, deliveryFee, total, message }: { product?: Product; gift?: { name: string; price: number }; card?: { text: string; price: number }; recipient: string; occasion: string; sender: string; hideSender: boolean; deliveryAt: string; deliveryFee?: number; total: number; message: string }) {
  return <aside className="gift-summary"><div className="eyebrow">معاينة آمنة</div><h2>مراجعة الإهداء</h2><dl><div><dt>المنتج</dt><dd>{product?.name || 'لم يُحدد بعد'}</dd></div><div><dt>الإضافة</dt><dd>{gift ? `${gift.name} · ${money(gift.price)}` : 'بدون إضافة'}</dd></div><div><dt>الكارت</dt><dd>{card ? `${card.text} · ${money(card.price)}` : 'بدون كارت'}</dd></div><div><dt>المستلم</dt><dd>{recipient || 'لم يُحدد بعد'}</dd></div><div><dt>المناسبة</dt><dd>{occasion || 'لم تُحدد بعد'}</dd></div><div><dt>المرسل</dt><dd>{hideSender ? 'مخفي عن المستلم' : sender || 'لم يُحدد بعد'}</dd></div><div><dt>موعد التوصيل</dt><dd>{deliveryAt || 'لم يُحدد بعد'}</dd></div></dl>{message && <blockquote>{message}</blockquote>}<div className="gift-total"><span>الإجمالي التقديري{typeof deliveryFee === 'number' ? ` · التوصيل ${money(deliveryFee)}` : ''}</span><b>{money(total)}</b></div><p className="disclaimer">هذه معاينة محلية فقط. لا تُرسل بيانات المستلم ولا تُنشئ طلباً حتى تفعيل Backend الآمن.</p></aside>
}

function GiftPageV2({ onAdd }: { onAdd: (productId: string, options: CartOptions) => void }) {
  const { products, giftConfig, publicConfig } = useCatalog(); const published = products.filter(item => item.orderable !== false && !item.demo); const [productId, setProductId] = useState(''); const [giftId, setGiftId] = useState(''); const [cardId, setCardId] = useState(''); const [recipient, setRecipient] = useState(''); const [recipientPhone, setRecipientPhone] = useState(''); const [occasion, setOccasion] = useState(''); const [province, setProvince] = useState(''); const [district, setDistrict] = useState(''); const [address, setAddress] = useState(''); const [deliveryAt, setDeliveryAt] = useState(''); const [sender, setSender] = useState(''); const [hideSender, setHideSender] = useState(false); const [message, setMessage] = useState(''); const [notes, setNotes] = useState(''); const [review, setReview] = useState(false); const [feedback, setFeedback] = useState('')
  const provinces = Object.keys(publicConfig.delivery); const selectedProvince = publicConfig.delivery[province]; const areas = selectedProvince?.areas || selectedProvince?.districts || {}; const selectedArea = areas[district]; const product = published.find(item => item.id === productId); const gift = giftConfig.addons.find(item => item.id === giftId && item.stock !== 0 && item.bouquetCompatible); const card = giftConfig.cards.find(item => item.id === cardId); const fee = selectedArea?.price; const total = (product?.price || 0) + (gift?.price || 0) + (card?.price || 0) + (fee || 0); const maxMessage = Math.min(2000, Math.max(1, Number(giftConfig.settings.maxCardMessageLength || 300))); const minDate = selectedArea?.preparationHours !== undefined ? new Date(Date.now() + selectedArea.preparationHours * 3600000).toISOString().slice(0, 16) : undefined
  const deliveryError = selectedArea && deliveryAt ? (() => { const date = new Date(deliveryAt); if (Number.isNaN(date.getTime())) return 'اختر موعداً صحيحاً.'; if (minDate && deliveryAt < minDate) return 'الموعد قبل وقت تجهيز الباقة.'; if (selectedArea.availableDays?.length && !selectedArea.availableDays.includes(date.getDay())) return 'هذا اليوم غير متاح للتوصيل.'; const slots = selectedArea.timeSlots || []; if (slots.length && !slots.some(slot => { const [start, end] = slot.split('-'); const value = deliveryAt.slice(11, 16); return Boolean(start && end && value >= start && value <= end) })) return 'هذه الفترة غير متاحة للتوصيل.'; return '' })() : ''
  useEffect(() => { if (!province && provinces[0]) setProvince(provinces[0]) }, [province, provinces.join('|')]); useEffect(() => { if (district && !areas[district]) setDistrict('') }, [province, district, Object.keys(areas).join('|')]); useEffect(() => { if (giftId && !gift) setGiftId('') }, [giftId, gift?.id])
  const reviewGift = (event: React.FormEvent) => { event.preventDefault(); setFeedback(''); if (!product || !selectedArea || !deliveryAt || deliveryError) { setFeedback('أكمل المنتج والمنطقة وموعداً متاحاً قبل المراجعة.'); return } setReview(true) }; const confirmPreview = () => { if (product) onAdd(product.id, { giftMessage: message, ...(card ? { card: { id: card.id, text: card.text, ...(card.image ? { image: card.image } : {}), message } } : {}), gifting: { addonIds: gift ? [gift.id] : [], ...(card ? { cardId: card.id, cardMessage: message } : {}) } }); setFeedback('تمت إضافة الهدية إلى السلة. بيانات الكارت والرسالة محفوظة داخل هذا السطر بشكل مستقل.'); setReview(false) }
  return <main className="page"><div className="container gift-page"><div className="page-intro"><div><div className="eyebrow">أرسل هدية</div><h1>خلّيها توصل <i>بإحساسك.</i></h1><p>اختر منتجاً منشوراً، تفاصيل التوصيل، ثم راجع كل خطوة قبل التأكيد.</p></div><Link className="btn btn-lime" to="/bouquet-builder">صمّم باقتك <Palette size={17} /></Link></div>{review ? <div className="gift-layout"><GiftSummaryV2 product={product} gift={gift} card={card} recipient={recipient} occasion={occasion} sender={sender} hideSender={hideSender} deliveryAt={deliveryAt} deliveryFee={fee} total={total} message={message} /><section className="panel form-panel"><h2>المعاينة النهائية</h2><p>يمكنك تعديل أي خطوة قبل التأكيد.</p><div className="form-actions"><button className="btn btn-dark" type="button" onClick={confirmPreview}>تأكيد المعاينة فقط <Check size={17} /></button><button className="btn btn-outline" type="button" onClick={() => setReview(false)}>تعديل التفاصيل</button></div>{feedback && <p className="form-message" role="status">{feedback}</p>}</section></div> : <div className="gift-layout"><form className="checkout-form gift-form" onSubmit={reviewGift}><h2>تفاصيل الإهداء</h2><label>المنتج أو الباقة<select required value={productId} onChange={event => setProductId(event.target.value)}><option value="">اختر منتجاً منشوراً</option>{published.map(item => <option key={item.id} value={item.id}>{item.name} · {money(item.price)}</option>)}</select></label>{!published.length && <EmptyState title="لا توجد منتجات منشورة" text="سيظهر هذا الاختيار عند نشر منتجات حقيقية في Firebase." link="/shop" />}<label>إضافة هدية اختيارية<select value={giftId} onChange={event => setGiftId(event.target.value)}><option value="">بدون إضافة</option>{giftConfig.addons.map(item => <option key={item.id} value={item.id}>{item.name} · {money(item.price)}</option>)}</select></label><label>كارت الإهداء<select value={cardId} onChange={event => setCardId(event.target.value)}><option value="">بدون كارت</option>{giftConfig.cards.map(item => <option key={item.id} value={item.id}>{item.text} · {money(item.price)}</option>)}</select></label><div className="field-grid"><label>اسم المستلم<input required value={recipient} onChange={event => setRecipient(event.target.value)} maxLength={120} /></label><label>هاتف المستلم<input required value={recipientPhone} onChange={event => setRecipientPhone(event.target.value)} inputMode="tel" maxLength={30} /></label><label>المناسبة<select required value={occasion} onChange={event => setOccasion(event.target.value)}><option value="">اختر المناسبة</option>{giftConfig.occasions.map(item => <option key={item.id} value={item.label}>{item.label}</option>)}</select></label><label>المحافظة<select required value={province} onChange={event => { setProvince(event.target.value); setDistrict(''); setDeliveryAt('') }}><option value="">اختر المحافظة</option>{provinces.map(name => <option key={name}>{name}</option>)}</select></label><label>المنطقة<select required value={district} onChange={event => { setDistrict(event.target.value); setDeliveryAt('') }}><option value="">اختر المنطقة</option>{Object.entries(areas).filter(([, area]) => area.enabled !== false).map(([name, area]) => <option key={name} value={name}>{name} — {money(area.price)}</option>)}</select></label><label>موعد التوصيل<input required type="datetime-local" min={minDate} value={deliveryAt} onChange={event => setDeliveryAt(event.target.value)} />{selectedArea?.deliveryAt && <small>{selectedArea.deliveryAt}</small>}{deliveryError && <small className="error-text">{deliveryError}</small>}</label></div><label>العنوان التفصيلي<textarea required value={address} onChange={event => setAddress(event.target.value)} maxLength={300} /></label><label>ملاحظات التوصيل<textarea value={notes} onChange={event => setNotes(event.target.value)} maxLength={300} /></label><div className="field-grid"><label>اسم المُرسل<input value={sender} onChange={event => setSender(event.target.value)} maxLength={120} disabled={hideSender} /></label><label className="check-field"><input type="checkbox" checked={hideSender} onChange={event => setHideSender(event.target.checked)} /> إخفاء اسم المُرسل عن المستلم</label></div><label>رسالة الكارت<textarea value={message} onChange={event => setMessage(event.target.value.slice(0, maxMessage))} maxLength={maxMessage} /><small>{message.length}/{maxMessage}</small></label>{feedback && <p className="form-message" role="status">{feedback}</p>}<div className="gift-actions"><button className="btn btn-dark" type="submit">مراجعة الإهداء <ArrowLeft size={17} /></button><Link className="btn btn-outline" to="/shop">اختيار منتج</Link></div></form><GiftSummaryV2 product={product} gift={gift} card={card} recipient={recipient} occasion={occasion} sender={sender} hideSender={hideSender} deliveryAt={deliveryAt} deliveryFee={fee} total={total} message={message} /></div>}</div></main>
}

function BouquetBuilderV2({ onAdd }: { onAdd: (productId: string, options: CartOptions) => void }) {
  const { giftConfig, products } = useCatalog(); const [selected, setSelected] = useState<Record<string, string>>({}); const [addons, setAddons] = useState<string[]>([]); const [cardId, setCardId] = useState(''); const [budget, setBudget] = useState(''); const [feedback, setFeedback] = useState(''); const groups: Array<[string, string, keyof GiftConfig]> = [['نوع الورد', 'flowerTypes', 'flowerTypes'], ['لون الورد', 'flowerColors', 'flowerColors'], ['عدد الورود', 'stemCounts', 'stemCounts'], ['التغليف', 'wrappings', 'wrappings'], ['لون التغليف', 'wrappingColors', 'wrappingColors'], ['الشريط', 'ribbons', 'ribbons']]; const choose = (key: string, id: string) => setSelected(current => ({ ...current, [key]: id })); const selectedPrice = groups.reduce((sum, [, key, group]) => sum + (((giftConfig[group] as Array<{ id: string; price: number }>) || []).find(item => item.id === selected[key])?.price || 0), 0); const addonPrice = addons.reduce((sum, id) => sum + (giftConfig.addons.find(item => item.id === id)?.price || 0), 0); const card = giftConfig.cards.find(item => item.id === cardId); const total = selectedPrice + addonPrice + (card?.price || 0); const budgetValue = budget ? Number(budget) : undefined; const overBudget = budgetValue !== undefined && Number.isFinite(budgetValue) && total > budgetValue
  const review = () => { if (!groups.every(([, key]) => selected[key])) { setFeedback('اختر قيمة من كل مجموعة منشورة قبل المراجعة.'); return } const baseProduct = products.find(item => item.orderable !== false && item.demo !== true); if (!baseProduct) { setFeedback('لا توجد باقة منشورة يمكن تخصيصها حالياً.'); return } onAdd(baseProduct.id, { gifting: { optionIds: selected, addonIds: addons, ...(card ? { cardId: card.id, cardMessage: '' } : {}) }, ...(card ? { card: { id: card.id, text: card.text, ...(card.image ? { image: card.image } : {}) } } : {}) }); setFeedback('تمت إضافة الباقة المخصصة إلى السلة مع حفظ كل الخيارات.'); }
  return <main className="page"><div className="container gift-page"><div className="page-intro"><div><div className="eyebrow">مصمم الباقات</div><h1>صمّم باقتك <i>خطوة خطوة.</i></h1><p>كل الخيارات والأسعار من Firebase. المعاينة وصفية وليست صورة تركيبية نهائية.</p></div><Link className="btn btn-outline" to="/send-a-gift">إرسال كهدية <Send size={17} /></Link></div><div className="builder-layout"><section className="builder-panel">{groups.map(([label, key, group]) => { const options = (giftConfig[group] as Array<{ id: string; label: string; price: number; image?: string }> || []); return <fieldset className="builder-step" key={key}><legend>{label}</legend><div className="choice-grid">{options.map(item => <button type="button" className={`choice ${selected[key] === item.id ? 'selected' : ''}`} onClick={() => choose(key, item.id)} key={item.id}>{item.image && <img src={item.image} alt="" />}{item.label}<small>{item.price ? `+ ${money(item.price)}` : 'بدون إضافة'}</small></button>)}</div>{!options.length && <p className="demo-note">لا توجد خيارات منشورة من المتجر بعد.</p>}</fieldset> })}<fieldset className="builder-step"><legend>الإضافات</legend><div className="choice-grid">{giftConfig.addons.filter(item => item.bouquetCompatible && item.stock !== 0).map(item => <button type="button" className={`choice ${addons.includes(item.id) ? 'selected' : ''}`} onClick={() => setAddons(current => current.includes(item.id) ? current.filter(id => id !== item.id) : [...current, item.id])} key={item.id}>{item.name}<small>+ {money(item.price)}</small></button>)}</div></fieldset><fieldset className="builder-step"><legend>الكارت</legend><div className="choice-grid"><button type="button" className={`choice ${!cardId ? 'selected' : ''}`} onClick={() => setCardId('')}>بدون كارت<small>بدون إضافة</small></button>{giftConfig.cards.map(item => <button type="button" className={`choice ${cardId === item.id ? 'selected' : ''}`} onClick={() => setCardId(item.id)} key={item.id}>{item.text}<small>+ {money(item.price)}</small></button>)}</div></fieldset><label className="field budget-field"><span>الميزانية بالدينار العراقي</span><input type="number" min="0" step="1" value={budget} onChange={event => setBudget(event.target.value)} /></label>{overBudget && <p className="error-text" role="alert">الإجمالي يتجاوز الميزانية المحددة.</p>}{feedback && <p className="form-message" role="status">{feedback}</p>}</section><aside className="builder-summary"><div className="builder-preview"><span>المعاينة الوصفية</span><strong>{groups.filter(([, key]) => selected[key]).length}/6 خطوات مكتملة</strong><small>هذه ليست صورة فوتوغرافية نهائية للباقة.</small></div><div className="gift-total"><span>التخصيص الحالي</span><b>{money(total)}</b></div><button type="button" className="btn btn-dark full" onClick={review}>مراجعة الباقة <ArrowLeft size={17} /></button></aside></div></div></main>
}

createRoot(document.getElementById('root')!).render(<HashRouter><App /></HashRouter>)

